(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["non"] = {"ui":{"skip":"Hlaupa til efnis","back":"← Aftr til AI-gile","lang.button":"Tunga: {name}","lang.dialog":"Veldu tungu","lang.search":"Leita at tungum","lang.none":"Engin tunga samsvarar","lang.notYet":"{name} er eigi þýdd enn","theme.aria":"Skipta yfirbragði: ljóst, dökkt eða svart","theme.toLight":"Skipta til ljóss yfirbragðs","theme.toDark":"Skipta til dökks yfirbragðs","theme.toBlack":"Skipta til svarts yfirbragðs (sannsvart, mjúkt fyrir OLED-skjái)","words.underline":"Strika undir þessi orð á síðunni","words.underlineHelp":"Hald músinni yfir orði með deplóttri línu, eða drep á þat, til at sjá hvat þat merkir.","words.col.todo":"Spjǫld þau er valin eru nú: sveitin tekr fyrst til þeira.","words.col.doing":"Hugvél ein vinnr nú at þessu spjaldi.","words.col.review":"Ein hugvél hefir lokit verkinu; ǫnnur lítr á þat, áðr en þat kemr til þín.","words.col.verify":"Bíðr þín: reyn þat ok seg, ef þat dugir.","words.col.team":"Skrár þínar eða andsvǫr, er bíða þess at sveitin taki við þeim.","words.col.done":"Lokit ok viðtekit.","index.title":"AI-gile: gervigreindarsveit þín, á einu borði","index.description":"AI-gile er kanban-borð fyrir gervigreindar-kóðasveitir. Þær vinna meðan þú sefr; þú færð einn stuttan haug af hlutum at ákveða, prófa ok samþykkja.","hero.logoAlt":"Tákn AI-gile-borðsins","hero.h1.html":"Gervigreindarsveit þín, á einu&nbsp;borði.","hero.alpha":"🐣 Lokat for-alfa","hero.alphaTitle":"Snemma ok ólokit: þökk fyrir at reyna!","hero.lede":"Þær smíða meðan þú sefr. Þú vaknar við einn stuttan haug: nokkrar spurningar, nokkra hluti at prófa, einn fjólubláan tígul eða tvá. Smelltu, samþykktu, ok aftr til kaffis þíns.","dl.windows":"Windows-forrit","dl.browser":"Rek þat í vafra þínum","dl.messenger":"📱 Messenger fyrir síma þinn","dl.soon":"Kemr brátt","dl.notify":"🔔 Seg mér, þá er þat opnast","dl.notifySmall":"Alfa eða beta","hero.secondary":"Agile, en sveitin þarf aldri kaffi á stand-up. (Þær halda stand-up þó.)","pitch.h2":"AI-gile í svá mörgum orðum sem þú vilt","pitch.lede":"Veldu lengd, frá einu orði til 144. Hver lengd er sín eigin lýsing, rituð fyrir þá stærð. Dragðu sleðann eða notaðu örvalyklana.","pitch.rangeLabel":"Lengd í orðum","pitch.dice":"🎲 önnur gerð","pitch.words.one":"{n} orð","pitch.words.other":"{n} orð","pitch.letters.one":"{n} stafr","pitch.letters.other":"{n} stafir","pitch.chars.one":"{n} tákn","pitch.chars.other":"{n} tákn","count.line.html.one":"{n} spjald á borðinu nú","count.line.html.other":"{n} spjöld á borðinu nú","people.humans.html.one":"👥 {n} maðr","people.humans.html.other":"👥 {n} menn","people.agents.html.one":"🤖 {n} erindreki","people.agents.html.other":"🤖 {n} erindrekar","people.working.html.one":"⚡ {n} at verki nú","people.working.html.other":"⚡ {n} at verki nú","pre.title":"AI-gile: eitthvat er í smíðum","pre.description":"Hér er eitthvat í smíðum: borð þar sem gervigreindarsveitir smíða þat er þú biðr um, ok kenna þér á leiðinni. Lokat for-alfa með vinum at sinni.","pre.h1":"Hér er eitthvat í smíðum. 🤫","pre.line":"Borð þar sem gervigreindarsveitir smíða þat er þú biðr um, ok kenna þér á leiðinni. Lokat for-alfa með vinum at sinni.","pre.btn":"🔔 Seg mér, þá er þat opnast","pre.peek":"Bak við glerit: hit sanna borð, lífs. Hvert spjald er litaðr strengr.","pre.peekFake":"Bak við glerit: svá lítr borð at verki út.","pre.night":"🌙 Næturvǫrðrinn ræðr · 😴 maðrinn hvílisk","features.aria":"Hvat þat gerir","f.pile.h":"Einn haugr handa þér","f.pile.html":"<b>Til þín</b> geymir allt sem bíðr þín, í öllum verkum: spurningar, hluti at prófa, störf er aðeins maðr má vinna. Röð þín segir hvat er næst ok hve lengi þat tekr.","f.sleep.h":"Sveitir er vinna meðan þú sefr","f.sleep.p":"Hvert verk hefr leiðtoga ok sveit gervigreindar-erindreka. Gerðu ummæli á spjald ok sveitin vaknar, vinnr verkit ok skilar því aftr með skrefum er þreyttr maðr má fylgja.","f.tester.h":"Gervigreindarprófari lítr fyrst á","f.tester.p":"Áðr en nokkut kemr til þín, fylgir prófari skrefunum í eftirmynd forritsins ok sýnir hvat hann sá, með skjámynd. Flettu gegnum þau er stóðust ok samþykktu með einum smelli.","f.proof.h":"Sannanir, eigi heit","f.proof.p":"Hver afhending sýnir hvat breyttist: skrárnar, muninn, skjámyndirnar. Þú þarft eigi at opna hvert forrit til at sjá hvárt því sé lokit.","f.chat.h":"Ræð við leiðtoga þína","f.chat.p":"Rönd í Discord-stíl: eitt tákn fyrir hvert verk, fjólubláir tíglar fyrir þat er þarfnast þín. Send leiðtoga hugmynd; hann gerir hana at spjöldum ok áætlun, með ✅ Go-hnappi.","f.tidy.h":"Heldr sjálfr reglu","f.tidy.p":"Skyld spjöld renna saman, ruglingsleg heiti eru löguð, ok tákna-athugun heldr kóðanum mjóum. Færra at skipta milli, minna at hugsa um.","f.private.h":"Þitt, á þinni eigin tölvu","f.private.li1":"Borðit gengr á þinni eigin vél ok svarar aðeins þér.","f.private.li2":"Einkaskilaboð milli manna eru dulrituð frá enda til enda.","f.private.li3":"Engir reikningar, engir eltarar, engar kökur.","f.lang.h":"Á þinni tungu","f.lang.p":"Yfir 120 tungur, frá norrœnu, velsku ok japönsku til sjóræningja, Yoda ok klingonsku, með skjótum rofa aftr til ensku fyrir iðnorð.","f.service.h":"Frá hugmynd til sannrar þjónustu","f.service.p":"Smíðaðir þú nökkut með gervigreind er menn nota nú? Merk þat sem þjónustu, ok taflan hjálpar þér at reka hana vel: uppitímaathuganir, opinber stöðusíða, atvik með eftirrannsókn, breytingar er þurfa Gakk, afrit athuguð hvern dag. Hjálpin kennir hvert skref á leiðinni.","msgr.h2":"AI-gile Messenger: sveit þín í pússi þínum","msgr.p1":"Mæl við gervigreindarsveit þína án þess at opna borðit. Spjalla við verkforingja þína ok vini þína, ok sé prófskref spjalds ok svara þeim, allt ór síma þínum.","msgr.p2":"Til at para hann, skanna QR-kóða á borði þínu. Fyrsta sinn? Vingjarnligt sýnispjall sýnir þér allt.","msgr.when":"Android fyrst, síðan vefútgáfa fyrir síma ok iPhone.","msgr.who":"Verkforingi þinn","msgr.b1":"Bótin fyrir dökkan hátt er búin. Viltu prófskrefin?","msgr.b2":"Já, gjarna!","msgr.b3":"1. Opna Uppsetning. 2. Vel Dökkt. Lítr þat rétt út?","tl.aria":"Tímalína frá fyrsta samtali til vegvísis","tl.h2":"Frá fyrsta spjalli til þess er næst kemr","tl.lede":"Sannar dagsetningar ok stundir, á þínu tímabelti. Eftir í dag er þat áætlun, án heitinna daga.","tl.today":"Í dag","tl.planned":"áætlat","tl.doing":"í verki","tl.cards.one":"{n} spjald","tl.cards.other":"{n} spjöld","join.h2":"Gakk í lið","join.lede":"AI-gile er smíðat af skeggjuðum undarligum manni með AuDHD ok nökkurum hugarstríðum, ok mörgum þolinmóðum erindrekum. Enn er þat einkamál, lokat alfa með vinum. Viltu reyna þá er þat opnast?","join.btn":"Skrá áhuga","join.small":"Vér sendum þér póst, ekki meira","footer.tag":"AI-gile. Engir eltarar, engar kökur, ekkert stand-up-kaffi.","footer.licence":"Starfsleyfi","footer.status":"Staða","footer.privacy":"Hvat vér geymum","footer.thanks":"Símtöl með þökk til ChilledChat","form.sending":"Sendi…","form.failed":"Þat tókst eigi: reyn aftr síðar.","form.offline":"Náði eigi til AI-gile: reyn aftr síðar.","form.keep":"Vér notum þetta einungis til at svara þér, ok eyðum því síðan. Engir eltarar, engar kökur.","form.keepLink":"Hvat vér geymum","interest.title":"AI-gile: seg mér þá er alfa opnast","interest.description":"Skildu eftir netfang þitt til at heyra þá er lokat alfa eða beta AI-gile opnast.","interest.h1":"🔔 Seg mér, þá er þat opnast","interest.lede":"AI-gile er í lokuðu for-alfa. Skildu eftir netfang þitt, ok vér skrifum einu sinni, þá er rúm er fyrir þik.","interest.email":"Netfang þitt","interest.which":"Hvert próf?","interest.alpha":"Lokat alfa: snemma, hrátt, margar breytingar","interest.beta":"Beta: stöðugra, síðar","interest.both":"Hvárt sem er, hvat sem fyrst kemr","interest.submit":"Settu mik á listann","interest.thanks":"Þökk! Þú ert á listanum.","licence.title":"AI-gile: starfsleyfi","licence.description":"Notar þú AI-gile í fyrirtæki þínu? Sæktu um ókeypis starfsleyfi.","licence.h1":"📜 Starfsleyfi","licence.lede":"Notar þú AI-gile í vinnu? Seg oss hverr þú ert ok hvat þú gerir. Ef þat gerir nokkut gott, er leyfit ókeypis.","licence.company":"Fyrirtæki","licence.website":"Vefsíða","licence.what":"Hvat þú gerir","licence.how":"Hversu þat hjálpar heiminum","licence.email":"Netfang","licence.submit":"Sækja um","licence.thanks":"Þökk! Vér svörum með pósti.","status.title":"Staða AI-gile","status.h1":"Staða AI-gile","status.quiet":"Allt er kyrrt","status.intro":"Starfar AI-gile nú? Þessi síða athugar vefinn, borðadeilingu, símtöl ok niðrhalit á 5 mínútna fresti.","status.up":"Starfar (svaraði á {ms} ms)","status.slow":"Svaraði eigi síðustu athugun, reyni aftr","status.down":"Niðri: svaraði eigi tveim síðustu athugunum","status.svc.web":"Vefr","status.svc.web.offers":"Þessi vefr: hvat AI-gile er, ok áhugaformit","status.svc.boards":"Borðadeiling","status.svc.boards.offers":"Opin borð, skilaboð milli vina ok boð","status.svc.calls":"Símtöl","status.svc.calls.offers":"Rödd, myndband ok skjádeiling í AI-gile","status.svc.download":"Niðrhal","status.svc.download.offers":"Windows-uppsetningin ok boðstenglar","status.checking":"Athuga…","status.offline":"Næ eigi til stöðuþjónustunnar nú (reyni aftr)","status.updated":"nýjat {ago}","status.justNow":"rétt nú","status.min":"{n}m síðan","status.hours":"{n}t síðan","status.days":"{n}d síðan","privacy.title":"AI-gile: hvat vér geymum","privacy.h1":"Hvat vér geymum","privacy.lede":"Í stuttu máli: aðeins þat er þú sendir oss, ok eigi lengi.","privacy.only":"Aðeins þat er þú sendir oss: þat er þú ritar í form, svá sem netfang þitt. Ekkert annat um þik.","privacy.sealed":"Þat er innsiglat svá at þjónn várr fái eigi lesit þat: í vafra þínum áðr en þat ferr (í eldri vafra, þegar er þat kemr). Aðeins várt eigit borð má opna þat.","privacy.server":"Því er eytt af þjóninum jafnskjótt sem þat nær borði váru. Allt er þar liggr enn eftir 30 daga er eytt engu at síðr.","privacy.board":"Vér geymum þat á borði váru aðeins unz vér höfum svarat þér, ok eyðum því þar síðan.","privacy.none":"Engir eltarar, engar kökur, engar mælingar.","privacy.local":"Mál þitt ok val milli ljóss ok dökks haldast í þínum eigin vafra. Þau eru aldri send oss.","privacy.ask":"Viltu at því sé eytt fyrr? Svara bréfi váru ok seg svá.","live.h2":"Sjá þat byggjask, lífs","live.caption":"Hvert spjald er hulit: þú sér líking verksins, eigi orðin.","live.watching.one":"lífs: {n} sér","live.watching.other":"lífs: {n} sjá","live.last.now":"Síðasta spjald var fært rétt nú","live.last.min.one":"Síðasta spjald var fært fyrir {n} mín.","live.last.min.other":"Síðasta spjald var fært fyrir {n} mín.","live.last.hour.one":"Síðasta spjald var fært fyrir {n} stund","live.last.hour.other":"Síðasta spjald var fært fyrir {n} stundum","live.last.day.one":"Síðasta spjald var fært fyrir {n} degi","live.last.day.other":"Síðasta spjald var fært fyrir {n} dögum","live.offline":"Lífs taflan hvílisk um stund. Kom aptr brátt.","live.cols":"Backlog|Til gerðar|Í verki|Sveitin lítr á|Til þín at testa|Til sveitar|Lokit","footer.models":"AI-gile rekr AI-líkön fyrir þik. Þat er þau segja ok gera er þeira eigit, kanna því þat áðr en þú trúir því.","privacy.ai.h":"AI-hlutrinn","privacy.ai.models":"AI-gile er borðit. Verkit gera AI-líkön frá öðrum félögum, svá sem Claude, Codex ok Gemini, á þínum eigin reikningum.","privacy.ai.check":"Þat er þau rita ok gera kemr frá þeim, ok má vera rangt. Kanna þat áðr en þú reiðir þik á þat eða sendir þat.","privacy.ai.files":"Þau breyta skrám ok keyra skipanir í möppum þeim er þú tengir. Geym afrit.","privacy.ai.send":"Þat er þú gefr líkani fer til þess félags er rekr þat, eptir þeira skilmálum. Hverr hefir sína skilmála ok kostnað.","privacy.ai.asis":"AI-gile er snemmbúin prófunarútgáfa, gefin eins ok hon er."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Erindrekar.","Falit."]},{"n":2,"texts":["Erindrekar, skipaðir.","Hugmyndir, smíðaðar.","Erindrekar vinna."]},{"n":3,"texts":["Kanban fyrir erindreka.","Hugmyndir verða eiginleikar.","Ókeypis, heima, prófat."]},{"n":5,"texts":["Borð þar er erindrekar smíða.","Þú ritar spjöld. Erindrekar smíða.","Ókeypis, heima, prófat, lítit skrýtit."]},{"n":8,"texts":["Ókeypis kanban-borð þar er gervigreindar-erindrekar vinna öll verkin.","Rit eina hugmynd. Erindrekar smíða hana. Þú samþykkir.","Agile fyrir einn mann ok marga þolinmóða erindreka."]},{"n":13,"texts":["Kanban-borð á tölvu þinni þar er gervigreindar-erindrekar taka spjöldin upp ok vinna þau.","Rit hugmynd. Sveit erindreka smíðar hana. Síðan lítr prófari á hana fyrir þik.","Ókeypis, engir reikningar né eltarar: borð, nokkrir erindrekar, ok þú ræðr öllu."]},{"n":21,"texts":["AI-gile er kanban-borð til at vinna með gervigreindar-kóðaerindrekum. Þeir taka spjöldin upp, hvert af öðru; þú prófar þau ok samþykkir.","Hvert verk fær leiðtoga ok sveit gervigreindar-erindreka. Gerðu ummæli á hvert spjald, ok þá tekr sveitin til starfa.","Ókeypis einkaborð til verka, er gengr á þinni eigin tölvu. Verkamennirnir eru erindrekar. Sá er segir já, ert þú."]},{"n":34,"texts":["Þú leggr hugmyndir á borð. Sveit gervigreindar-erindreka gerir þær at starfandi eiginleikum, prófar þá ok skilar þeim aftr með skrefum til at reyna. Ekkert telst lokit fyrr en þú segir svá.","AI-gile er heimagert kanban-borð er Rich smíðaði með mikilli hjálp erindreka þeirra er þat nú stýrir. Þat er ókeypis, gengr á tölvu þinni ok er deilt með vinum, eigi selt.","Hugsaðu þér venjulegt kanban-borð, með dálkum frá Backlog til Lokit, nema at spjöldin eru tekin af gervigreindar-erindrekum. Þeir segja frá framvindu, spyrja þá er þeir sitja fastir, ok bíða ávallt eftir þumli þínum upp."]},{"n":55,"texts":["AI-gile er kanban-borð þar er sveitin er gerð af gervigreindar-erindrekum. Hvert verk hefr leiðtoga er áætlar verkit ok hjálparmenn er smíða þat. Þá er eiginleiki er búinn, reynir gervigreindar-prófari hann ok tekr skjámynd, ok þá lendir hann á hauginum þínum. Samþykktu hann, eða gerðu ummæli, ok þeir vinna hann upp aftr.","Þat hófst sem leið eins manns til at halda utan um margar kóðalotur með gervigreind í senn, ok óx at réttu borði. Þat gengr á vél þinni, krefst engra reikninga ok hefr enga eltara. Þat er ókeypis fyrir vini ok forvitna. Þat er ok ólokit, svá búst við hrjúfum brúnum ok einni óvæntri uppákomu.","Hér er heiðarlega útgáfan. Þú verðr enn at eiga hugmyndirnar, ok þú verðr enn at líta á árangrinn. Þat er AI-gile gerir, er allt þar í milli: þat heldr spjöldunum í röð, vekr réttan erindreka þá er þú gerir ummæli, sýnir nákvæmlega hvat breyttist, ok safnar öllu í einn stuttan haug handa þér."]},{"n":89,"texts":["AI-gile er ókeypis kanban-borð er þú rekr á þinni eigin tölvu. Í stað manna hefr hvert verk sveit gervigreindar-erindreka: leiðtoga er gerir hugmyndir þínar at spjöldum ok áætlun, ok hjálparmenn er taka spjöldin í forgangsröð. Þá er eitthvat er smíðat, fylgir gervigreindar-prófari prófunarskrefunum ok sýnir þér hvat hann sá. Síðan bíðr þat í einum haug er heitir Til þín. Þú samþykkir þat, eða þú gerir ummæli ok sveitin reynir aftr. Ekkert kemst nokkurn tíma í Lokit án þín.","Nokkrir eiginleikar er þú væntir kannski eigi. Næturvörðr heldr Til gerðar-dálkinum fullum meðan þú sefr ok velr spjöld er þurfa eigi svar frá þér. Teljari sýnir hversu mikit erindrekarnir hafa notat í dag ok þessa viku, ok Engin tákn-hátr segir þeim at hætta at eyða. Þú mátt senda vinum skilaboð, ok einkaskilaboð eru dulrituð frá enda til enda. Borðit talar um 120 tungur, þar á meðal norrœnu, sjóræningja ok klingonsku. Ekkert af þessu kostar eyri, ok engi reynir at selja þér þat heldr.","AI-gile er lítit, persónulegt verk, eigi fyrirtæki. Rich vildi gæta margra gervigreindar-kóðaverka án þess at opna hvert forrit til at líta á þau, svá hann ok erindrekarnir smíðuðu borð til þess, ok notuðu síðan borðit til at smíða afganginn af sér sjálfu. Þat er í lokuðu for-alfa, sem merkir at þat virkar, mestanpart, fyrir fáeina vini. Hér er engin verðsíða, ekkert fréttabréf ok engin vaxtaráætlun. Ef þetta hljómar gagnlegt, mátt þú biðja um at reyna þat þá er þat opnast örlítit meira."]},{"n":144,"texts":["AI-gile er kanban-borð fyrir einn mann ok marga gervigreindar-erindreka. Þat gengr á þinni eigin tölvu ok er alveg ókeypis. Þú bætir við verkum, ok hvert verk fær leiðtoga ok litla sveit. Þú ræðr við leiðtogann, líkt ok á Discord, ok lýsir hugmynd; leiðtoginn gerir hana at spjöldum ok áætlun, ok bíðr þess at þú ýtir á Go. Sveitin vinnr sig gegnum spjöldin í forgangsröð, með einföldu skipanalínutóli gerðu fyrir mállíkön. Áðr en nokkut kemr aftr til þín, fylgir gervigreindar-prófari skrefunum í eftirmynd forritsins ok festir við skjámynd. Lokit verk lendir á hauginum þínum með breyttum skrám ok muninum. Þú samþykkir þat, eða þú skilr eftir ummæli, ok sveitin vaknar ok reynir aftr. Aðeins þú mátt færa spjald til Lokit.","Dagr með AI-gile, í grófum dráttum. At kveldi skilr þú eftir nokkur ummæli: þessi hnappr er á röngum stað, sá listi ætti at vera raðaðr, gætum vér fengit dökkan hátt. Þú ferr at sofa. Erindrekarnir lesa ummælin, gera breytingarnar, prófa þær ok skila þeim aftr til þín. Ef Til gerðar tæmist, fyllir næturvörðrinn þat úr backlog með spjöldum er þurfa ekkert svar frá þér. At morgni er þar einn stuttr haugr: nokkrar spurningar ok fáeinir hlutir at reyna, hver með skrefum er syfjaðr maðr má fylgja ok skjámynd af því at þat virkar. Þú smellir þig gegnum, samþykkir góðu spjöldin ok sendir hin aftr. Teljari sýnir hvat allt þetta notaði, ok Engin tákn-hátr er til fyrir magrar vikur. Síðan etr þú morgunverð, er erindrekarnir fá enn eigi hjálpat með.","Fyrst, hvat AI-gile er eigi. Þat er eigi sprotafyrirtæki, þat er eigi til sölu, ok engi safnar gögnum þínum. Þat er ókeypis borð er gengr á tölvu þinni, án reikninga, eltara eða kaka. Hvat þat er: einn snyrtiligr staðr til at sjá öll gervigreindar-kóðaverk þín senn, með sveit erindreka er vinnr spjöldin ok þik er tekr ákvarðanirnar. Þat steypir skyldum spjöldum saman, lagar ruglingsleg heiti ok fylgist með hversu mjór kóðinn helzt. Þat talar um 120 tungur, frá norrœnu til sjóræningja ok klingonsku. Vinir mega senda hverr öðrum skilaboð, einkaliga ok dulrituð. Þat var smíðat af Rich ok mörgum þolinmóðum erindrekum, er mestanpart notuðu þat sjálfir. Þat er í lokuðu for-alfa, svá þat er hrjúft sums staðar. Ef þat hljómar skemmtiligt, bið vel, ok kannski kemst þú snemma inn."]}],"quips":{"1":"Eitt orð. Djarft. Kannski of djarft.","3":"Þrjú orð. Þegar heiðarlegra en flestar vörusíður.","8":"Átta orð. Enn styttra en stand-up.","21":"Lengdirnar eru annars story points. Auðvitað eru þær þat.","55":"Fimmtíu ok fimm orð. Tvö spjöld lukust meðan þú last þetta.","144":"Þat var hit langa. Ekkert 233 er til. Erindrekarnir eru farnir at sofa."}},"timeline":{"first-idea.name":"Hin fyrsta hugmynd","first-idea.line":"Hit allra fyrsta samtal, áðr en nokkur kóði var til.","first-board.name":"Hit fyrsta borð","first-board.line":"Borð er heldr utan um sína eigin smíð: spjöld, dálka, draga ok sleppa, verk.","team-roles.name":"Sveit ok hlutverk","team-roles.line":"Erindrekasnið, sveitarsnið, rými ok hverr gerir hvat.","install.name":"Uppsetning ok útgáfur","install.line":"Zip-skrá er vinr má setja upp, sjálfnýjun, rásir ok afturhvarf.","usage-saver.name":"Notkunarsparnaðr","usage-saver.line":"Mæla hvat keyrslur kosta, halda kóðanum mjóum, spara mörk þín.","friends.name":"Vinir ok deiling","friends.line":"Einkaskilaboð, dulrituð miðlun, boð, hlutverk ok sameiginleg verk.","languages.name":"Tungur","languages.line":"Hver skjátexti í tungumálsskrá, með hollenzku ok flæmsku fyrst.","ai-tester.name":"Gervigreindarprófari","ai-tester.line":"Prófari lítr á hverja afhending fyrst ok sýnir hvat hann sá.","website.name":"Vefsíðan","website.line":"aigile.lol, forsmekkrinn ok þessi tímalína.","streaming.name":"Spjall ok streymi","streaming.line":"Discord, Twitch, OBS, streymishátr, GIF ok tjáknmyndir.","no-ai.name":"Útgáfa án gervigreindar","no-ai.line":"Borð fyrir þá er kóða án gervigreindar, ok opinber borð.","night-watch.name":"Næturvarðhald","night-watch.line":"Vörðr ok Scrum-meistari halda sveitunum við efnit meðan þú sefr.","p-more.name":"Allt annat","p-more.line":"Minni hugmyndir er enn bíða síns tíma.","p-android.name":"Sími ok Android","p-android.line":"Nálgast borð þitt úr síma, síðan sérstakt Android-forrit.","p-release.name":"Alfa ok lengra","p-release.line":"Lokat alfa, hin lifandi vefsíða, síðan beta.","p-languages.name":"Fleiri tungur","p-languages.line":"130 tungur, ok kafhamr fyrir þá er nema.","p-engines.name":"Fleiri gervigreindarvélar","p-engines.line":"Vel Claude, Codex, Gemini, Copilot eða Cursor fyrir hvern erindreka.","p-pro.name":"Atvinnuháttr","p-pro.line":"Áhættumerki, sameiningarhlið, atvikaspjöld ok handrið.","p-self.name":"Gæta þín","p-self.line":"Þreytuhátr, sjálfsumönnunaráminningar ok 4:20.","p-servers.name":"Þjónar ok umfang","p-servers.line":"Almennar þjónastillingar, hlutverk ok áætlun fyrir vöxt.","p-livestream.name":"Streymisviðbætr","p-livestream.line":"Twitch-spjall, eigin tjáknmyndir ok opinbert beint yfirlit."},"words":{"button":"📖 Iðnorð","h":"📖 Orð skýrð","intro":"Ókeypis kennsla á einföldu máli: hvert orð er þú mætir frá fyrstu hugmynd til þjónustu er menn treysta, með Agile, smíð, öryggi ok starfi með gervigreind á leiðinni.","search":"Leita orðs…","none":"Ekkert orð samsvarar því.","close":"Loka","count":{"one":"{count} orð","other":"{count} orð"},"groups":[{"id":"idea","name":"💡 Hugmynd ok könnun"},{"id":"plan","name":"🗺️ Áætlun verks"},{"id":"agile","name":"🔁 Lipr starfsháttr"},{"id":"build","name":"🛠️ At smíða"},{"id":"test","name":"🧪 Prófun ok gæði"},{"id":"change","name":"🔀 At breyta með öryggi"},{"id":"run","name":"🛎️ At reka þjónustu"},{"id":"sec","name":"🔒 Öryggi ok einkamál"},{"id":"ai","name":"🤖 Starf með gervigreind"},{"id":"money","name":"💰 Fé ok leyfi"}],"list":[{"id":"discovery","g":"idea","word":"Könnun","text":"Fyrsta stig, áðr en nokkut er smíðat, þá er leitat hvert vandamál er vert at leysa ok fyrir hvern.","also":["discovery","discovery phase","könnunarstig"]},{"id":"problemstmt","g":"idea","word":"Vandamálslýsing","text":"Ein eða tvær setningar er segja hverr á við vanda, hvat þat er ok hví þat skiptir máli, svá at allir stefni at einu marki.","also":["problem statement","problem statements","vandamálslýsing"]},{"id":"user","g":"idea","word":"Notandi","text":"Maðr sá er notar þat er þú smíðar. Þarfir hans eru ástæða verksins.","also":["user","users","notandi","notendr"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Hagsmunaaðili","text":"Hverr sá er lætr sér annt um hversu verkit fer eða verðr fyrir áhrifum þess, svá sem þeir er gjalda fyrir, nota eða styðja þat.","also":["stakeholder","stakeholders","hagsmunaaðili"]},{"id":"persona","g":"idea","word":"Persóna","text":"Tilbúinn en trúlegr maðr er stendr fyrir eina tegund notanda, svá at sveitin megi spyrja: „Mun Sam þykja þetta auðvelt?“","also":["persona","personas","persóna"]},{"id":"userresearch","g":"idea","word":"Notendarannsókn","text":"At tala við raunverulega menn ok horfa á þá til at læra hvers þeir þurfa, í stað þess at gizka.","also":["user research","user interviews","notendarannsókn"]},{"id":"journey","g":"idea","word":"Ferð notanda","text":"Þau skref er maðr stígr til at koma einhverju af, frá því er hann heyrir fyrst af því unz hann lýkr, einnig utan vöru þinnar. Þegar þú teiknar þat sést hvar hann festisk.","also":["user journey","user journeys","customer journey","ferð notanda"]},{"id":"painpoint","g":"idea","word":"Sársaukapunktr","text":"Þat er angrar menn eða tefr þá nú. Góðar vörur taka sársaukapunkta burt.","also":["pain point","pain points","sársaukapunktr"]},{"id":"assumption","g":"idea","word":"Ætlun","text":"Þat er þú trúir en hefir enn eigi kannat. Ef ætlanir eru ritaðar sést hvat skal fyrst prófa.","also":["assumption","assumptions","ætlun"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Tilgáta","text":"Bezta gizkan er þú ætlar at kanna, með því er þú væntir at verði, svá sem „menn skrá sik ef fyrsti mánuðr er ókeypis“.","also":["hypothesis","hypotheses","tilgáta"]},{"id":"experiment","g":"idea","word":"Tilraun","text":"Lítil áætluð prófun til at vita hvárt hugmynd dugir, áðr en mikit er lagt í hana.","also":["experiment","experiments","tilraun"],"noTip":1},{"id":"poc","g":"idea","word":"Sönnun hugmyndar (PoC)","text":"Skjót ok hrá tilraun til at sjá hvárt hugmynd megi yfirleitt starfa. Henni er oftast kastat er svarit er fengit.","also":["PoC","proof of concept","sönnun hugmyndar"]},{"id":"prototype","g":"idea","word":"Frummynd","text":"Fyrsta fyrirmynd vörunnar, oft myndir er má þrýsta á, til at reyna hugmyndina á mönnum áðr en hún er smíðuð til fulls.","also":["prototype","prototypes","frummynd"]},{"id":"wireframe","g":"idea","word":"Grindarmynd","text":"Einfalt uppkast skjás er sýnir hvar hlutir standa, án lita eða raunverulegs efnis.","also":["wireframe","wireframes","grindarmynd"]},{"id":"mockup","g":"idea","word":"Fyrirmyndarmynd","text":"Nákvæm mynd þess hvernig skjár mun líta út, með raunverulegum litum ok texta, en ekkert starfar enn.","also":["mockup","mockups","mock-up","mock-ups","fyrirmyndarmynd"]},{"id":"bizcase","g":"idea","word":"Rekstrarrök","text":"Ástæður til at vinna verk: hvat þat kostar, hvat þat aflar eða sparar, ok áhættur.","also":["business case","business cases","rekstrarrök"]},{"id":"feasibility","g":"idea","word":"Framkvæmanleiki","text":"Hvárt hlutr megi í raun smíða ok varðveita með þeim tíma, fé ok kunnáttu er þú hefir.","also":["feasibility","framkvæmanleiki"]},{"id":"outcome","g":"idea","word":"Árangr","text":"Sú breyting er þú vilt fyrir menn, svá sem færri gleymd mót. Hún skiptir meira máli en hversu mikit þú smíðar.","also":["outcome","outcomes","árangr"],"noTip":1},{"id":"output","g":"idea","word":"Afurð","text":"Þat er sveitin gerir, svá sem nýr skjár eða skýrsla. Þótt þat sé gert er eigi sagt at þat hjálpi nokkrum.","also":["output","outputs","afurð"],"noTip":1},{"id":"successmetric","g":"idea","word":"Árangursmælikvarði","text":"Tala er sýnir hvárt verkit gerði þat er því var ætlat, svá sem fleiri er ljúka pöntun sinni.","also":["success metric","success metrics","árangursmælikvarði"]},{"id":"kpi","g":"idea","word":"Lykilmælikvarði (KPI)","text":"Mikilvæg tala er þú fylgist með til at sjá hvárt vel gengr, svá sem skráningar á viku.","also":["KPI","KPIs","key performance indicator","lykilmælikvarði"]},{"id":"okr","g":"idea","word":"Markmið ok lykilárangr (OKR)","text":"Háttr at setja mark: markmiðit segir hvat þú vilt, ok nokkrir lykilárangrar eru tölurnar er sýna at þú náðir því.","also":["OKR","OKRs","markmið ok lykilárangr"]},{"id":"product","g":"plan","word":"Vara","text":"Þat er smíðat er ok varðveitt fyrir notendr sína, svá sem forrit, vefsíða eða verkfæri.","also":["product","products","vara"],"noTip":1},{"id":"vision","g":"plan","word":"Sýn vörunnar","text":"Stutt yfirlýsing um hverjum varan hjálpar ok hvert hon stefnir til langframa.","also":["product vision","vision statement","sýn vörunnar"]},{"id":"po","g":"plan","word":"Vöruhaldari (PO)","text":"Sá er ræðr hvat skal smíða ok í hverri röð, svá at sveitin vinni ávallt þat er mest skiptir. Í AI-gile er þat þú.","also":["PO","product owner","product owners","vöruhaldari"]},{"id":"pm","g":"plan","word":"Vörustjóri (PM)","text":"Sá er gætir stefnu vöru: hver vandamál hon leysir, fyrir hvern ok hví. PM getr einnig merkt verkstjóra, svá at gáðu hvárt er.","also":["PM","product manager","product managers","vörustjóri"]},{"id":"projmgr","g":"plan","word":"Verkstjóri","text":"Sá er heldr verki á tíma ok innan fjárhags, ok fylgist með hverr gerir hvat ok hvenær.","also":["project manager","project managers","verkstjóri"]},{"id":"roadmap","g":"plan","word":"Vegvísir","text":"Gróf áætlun þess er kemr næstu mánuði, í röð. Hon sýnir stefnu, eigi nákvæma daga, ok breytisk er þú lærir.","also":["roadmap","roadmaps","vegvísir"]},{"id":"milestone","g":"plan","word":"Áfangi","text":"Punktr í verki sem vert er at marka, svá sem „fyrsta gerð í loft“ eða „100 notendr“.","also":["milestone","milestones","áfangi"]},{"id":"mvp","g":"plan","word":"Minnsta nothæf vara (MVP)","text":"Minnsta gerð vöru er enn gagnast raunverulegum mönnum, svá at þú megir læra af þeim snemma.","also":["MVP","MVPs","minimum viable product","minnsta nothæf vara"]},{"id":"requirement","g":"plan","word":"Krafa","text":"Þat sem fullgerð vara skal gera eða vera.","also":["requirement","requirements","krafa"],"noTip":1},{"id":"scope","g":"plan","word":"Umfang","text":"Hvat er innan verksins ok, jafn mikilvægt, hvat er utan þess.","also":["scope","in scope","out of scope","umfang"]},{"id":"scopecreep","g":"plan","word":"Umfangsskrið","text":"Þá er æ meira bætisk við verkit smátt ok smátt, án þess at nokkur samþykki auka tíma eða kostnað, svá at því lýkr aldri.","also":["scope creep","feature creep","umfangsskrið"]},{"id":"feature","g":"plan","word":"Eiginleiki","text":"Eitt þat er varan má gera fyrir menn, svá sem „endrstilla lykilorð“.","also":["feature","features","eiginleiki"],"noTip":1},{"id":"epic","g":"plan","word":"Stórsaga","text":"Stórt stykki verks, of mikit til at vinna í einu, svá at því er skipt í smærri spjöld.","also":["epic","epics","stórsaga"]},{"id":"story","g":"plan","word":"Notandasaga","text":"Lítit stykki verks ritat frá sjónarhorni notanda: „Sem kaupandi vil ek geyma körfu mína, svá at ek megi ljúka síðar.“ Þat hefr samtal um hvat skal smíða.","also":["user story","user stories","notandasaga"]},{"id":"ac","g":"plan","word":"Samþykkisskilyrði (AC)","text":"Þær prófanir er eitt spjald verðr at standast til at teljask lokit, samþykktar áðr en verk hefst, svá sem „karfan er enn þar eftir at ek hefi skráð mik út ok inn aftr“.","also":["acceptance criteria","AC","samþykkisskilyrði"]},{"id":"task","g":"plan","word":"Verkþáttr","text":"Eitt starf er vinna skal, oft eitt lítit skref stærri sögu.","also":["task","tasks","verkþáttr"],"noTip":1},{"id":"ticket","g":"plan","word":"Miði","text":"Annat orð fyrir spjald: eitt stykki verks eða ein beiðni, fylgt frá upphafi til enda.","also":["ticket","tickets","miði"]},{"id":"priority","g":"plan","word":"Forgangr","text":"Hversu mikilvægt eða brýnt eitthvat er í samanburði við allt annat, svá at mikilvægasta verk fari fyrst.","also":["priority","priorities","forgangr"],"noTip":1},{"id":"prioritise","g":"plan","word":"Forgangsröðun","text":"At raða verki eftir mikilvægi. Algengr háttr er MoSCoW: Must have (skal vera), Should have (ætti at vera), Could have (mætti vera), Won’t have this time (verðr eigi nú).","also":["prioritisation","MoSCoW","forgangsröðun"]},{"id":"estimate","g":"plan","word":"Mat","text":"Bezta gizkan um hversu stórt eða langt stykki verks er. Þat er gizkan, eigi heit.","also":["estimate","estimates","estimation","mat"],"noTip":1},{"id":"storypoints","g":"plan","word":"Sögustig","text":"Háttr at gizka stærð verks með því at bera spjöld saman („um tvöfalt stærra en hitt“) í stað stunda. Þau eru eigi til at bera sveitir saman.","also":["story point","story points","sögustig"]},{"id":"tshirt","g":"plan","word":"Bolastærðir","text":"At gizka stærð verks sem S, M, L eða XL. Skjótt ok nógu gott til fyrstu áætlunar.","also":["T-shirt sizing","t-shirt sizes","bolastærðir"]},{"id":"poker","g":"plan","word":"Áætlunarspil","text":"Leikr til at meta: allir sýna stærðarspjald samtímis, síðan skýra sá er hæst ok sá er lægst valdi hví.","also":["Planning poker","Scrum poker","áætlunarspil"]},{"id":"dependency","g":"plan","word":"Háðleiki","text":"Er eitt stykki verks má eigi hefjask eða ljúkask fyrr en annat er gert.","also":["dependency","dependencies","háðleiki"]},{"id":"blocker","g":"plan","word":"Tálmi","text":"Hvat sem hindrar verk í at ganga fram nú, svá sem svar er vantar eða brotit verkfæri.","also":["blocker","blockers","tálmi"]},{"id":"deadline","g":"plan","word":"Frestr","text":"Sá dagr er verki skal lokit vera.","also":["deadline","deadlines","frestr"],"noTip":1},{"id":"deliverable","g":"plan","word":"Afhendingarhlutr","text":"Áþreifanlegr hlutr er verkit skilar af sér, svá sem síða er starfar eða skýrsla.","also":["deliverable","deliverables","afhendingarhlutr"]},{"id":"forecast","g":"plan","word":"Spá","text":"Spá um hvat líklegt er at verði, svá sem hvenær verki lýkr, byggð á því er þú veizt til þessa.","also":["forecast","forecasts","spá"],"noTip":1},{"id":"metric","g":"plan","word":"Mælikvarði","text":"Hvat sem þú mælir ok fylgist með yfir tíma, svá sem síðuheimsóknir eða hversu lengi lagfæring tekr.","also":["metric","metrics","mælikvarði"]},{"id":"feedback","g":"plan","word":"Endrmæli","text":"Þat er menn segja þér um verk þitt, gott ok illt. At fá þat snemma ok oft er hjarta Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Biðlisti hugmynda ok verks sem eigi er enn áætlat, með því mikilvægasta efst. Ekkert þar er unnit unz þat flyzt í Til gerðar."},{"id":"sprint","g":"agile","word":"Sprint","text":"Stutt, föst starfahrina (oft ein eða tvær vikur, aldri meira en mánuðr) með marki ok samþykktu safni spjalda til at ljúka.","also":["sprints"]},{"id":"standup","g":"agile","word":"Fundr","text":"Skjótr dagligr stöðufundr: hvat hverr liðsmaðr gerði, hvat hann gerir næst, ok hvat tálmar honum. Í Scrum heitir þat dagfundr (daily scrum).","also":["standup","stand-ups","daily scrum","daily stand-up","dagfundr"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Vinnuháttr þar sem spjöld flytjask yfir dálka borðs (svá sem Til gerðar, Í verki, Lokit) ok sveitin takmarkar hversu mikit er í verki í senn, svá at verk haldi áfram at streyma."},{"id":"wip","g":"agile","word":"WIP-mark","text":"WIP er stytting á work in progress (verk í gangi). WIP-mark er mesti fjöldi spjalda er dálkr skal geyma í senn, svá at sveitin ljúki hlutum áðr en hún hefr fleiri.","also":["WIP"]},{"id":"dod","g":"agile","word":"Skilgreining um Lokit","text":"Stuttr gátlisti sveitarinnar um hvat „lokit“ merkir, svá sem prófat ok skýrt, áðr en spjald er fengit þér. Tvíburi hans, Skilgreining um Búit, segir nær spjald er nógu ljóst til at hefja.","also":["Definition of Ready","DoD","DoR","skilgreining um búit"]},{"id":"retro","g":"agile","word":"Endrlit","text":"Regluleg endrlitning á hvernig sveitin vinnr, til at verða ásátt um eitt eða tvö atriði til at gera betr næst. Stytting á retrospective. Í AI-gile stingr endrlit upp á breytingu á starfsháttum sveitarinnar, ok þú segir Gakk eða Eigi enn.","also":["endrliti","endrlits","retro","retrospective"]},{"id":"swarm","g":"agile","word":"Sveimr","text":"Allir á dekk: margir leggja annat verk frá sér til at lagfæra eitt brýnt mál saman unz því er lokit. Í AI-gile hjálpar hver sveit við eitt verk, en önnur verk bíða á meðan.","also":["sveim","sverm","swarm"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Í Scrum sá maðr er hjálpar sveitinni at vinna vel: ryðr úr vegi því er tálmar, heldr fundum á réttri braut ok þjálfar góðar venjur, án þess at drottna yfir nokkrum. Í AI-gile sér Aðalfundarstjórinn föst spjöld, hvetr sveitirnar ok minnir þik á hvat bíðr, í öllum verkum.","also":["Aðalfundarstjóri","fundarstjóri","Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile (lipr háttr)","text":"Háttr at vinna í litlum skrefum: smíða lítit, sýna raunverulegan árangr oft, læra af því er menn segja ok breyta áætlun á leiðinni, í stað þess at ráðgera allt fyrirfram.","also":["Agile","Agile development","agile ways of working","lipr háttr"]},{"id":"manifesto","g":"agile","word":"Yfirlýsing Agile","text":"Stutt yfirlýsing er hugbúnaðarsmiðir rituðu árit 2001. Hon setr menn, starfandi árangr, náit samstarf við kaupendr ok viðbragð við breytingum fram yfir þungar áætlanir ok skjalavinnu.","also":["Agile Manifesto","Manifesto for Agile Software Development","yfirlýsing Agile"]},{"id":"waterfall","g":"agile","word":"Fossamódel","text":"Eldri vinnuháttr: ráðgera allt, smíða síðan allt, prófa síðan allt, eitt stig eftir annat. Breytingar síðla eru erfiðar ok dýrar.","also":["waterfall","waterfall model","fossamódel"]},{"id":"iteration","g":"agile","word":"Umferð","text":"Ein umferð at smíða eitthvat, kanna þat ok bæta. Agile-starf er keðja slíkra, ok sprint er ein tegund.","also":["iteration","iterations","umferð"]},{"id":"increment","g":"agile","word":"Viðbót","text":"Nýr starfandi hluti er bætisk við vöruna í sprint eða umferð, ok fellr við þat er fyrir var.","also":["increment","increments","viðbót"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Vinsæll Agile-háttr: lítil sveit vinnr í stuttum sprintum at marki, með ákveðnum hlutverkum ok fáeinum föstum fundum til at ráðgera, kanna ok bæta."},{"id":"scrumteam","g":"agile","word":"Scrum-sveit","text":"Sá litli hópr er vinnr verkit í Scrum: vöruhaldari, Scrum Master ok smiðir.","also":["Scrum team","Scrum teams","Scrum-sveit"]},{"id":"ceremonies","g":"agile","word":"Scrum-fundir","text":"Föstu fundirnir í Scrum: sprint-áætlun, dagfundr, sprint-skoðun ok endrlit. Margir kalla þá athafnir (ceremonies).","also":["Scrum events","ceremonies","Scrum ceremonies","Scrum-fundir"]},{"id":"sprintplan","g":"agile","word":"Sprint-áætlun","text":"Fundr í upphafi sprints þar sem sveitin verðr ásátt um hví sprintit skiptir máli, hver spjöld hon tekr ok hvernig hefja skal.","also":["Sprint planning","planning meeting","sprint-áætlun"]},{"id":"sprintgoal","g":"agile","word":"Sprint-mark","text":"Ein setning er segir hvat sprint er til. Smá störf mega breytask á leiðinni, svá lengi sem markinu er náð.","also":["Sprint goal","sprint goals","sprint-mark"]},{"id":"sprintbacklog","g":"agile","word":"Sprint-biðröð","text":"Spjöldin er valin eru fyrir núverandi sprint, með áætlun sveitarinnar um at vinna þau.","also":["Sprint backlog","sprint backlogs","sprint-biðröð"]},{"id":"productbacklog","g":"agile","word":"Vörubiðröð","text":"Allr raðaðr listi þess er smíða má fyrir vöruna, mikilvægast efst. Hann breytisk stöðugt er þú lærir.","also":["Product backlog","product backlogs","vörubiðröð"]},{"id":"productgoal","g":"agile","word":"Vörumark","text":"Sá meiri árangr er varan stefnir at, er hjálpar sveitinni at velja hvat gera skal næst.","also":["Product goal","product goals","vörumark"]},{"id":"refinement","g":"agile","word":"Fágun biðraðar","text":"At fara reglulega yfir biðröðina til at laga, skipta, raða ok bæta smáatriðum við spjöld, svá at þau séu búin til töku. Einnig kallat backlog grooming.","also":["backlog grooming","refinement","Backlog refinement","fágun biðraðar"]},{"id":"sprintreview","g":"agile","word":"Sprint-skoðun","text":"Fundr í lok sprints þar sem sveitin sýnir hvat hon lauk ok heyrir hvat menn hyggja, til at ráða hvat kemr næst.","also":["Sprint review","sprint reviews","sprint-skoðun"]},{"id":"demo","g":"agile","word":"Sýning","text":"At sýna lokit verk starfandi, í beinni, þeim er báðu um þat.","also":["demo","demos","sýning"],"noTip":1},{"id":"timebox","g":"agile","word":"Tímarammi","text":"Ákveðinn tími fyrir eitthvat. Er hann er liðinn hættir þú, þótt eigi sé allt gert.","also":["timebox","timeboxed","timeboxes","tímarammi"]},{"id":"velocity","g":"agile","word":"Hraði sveitar","text":"Hversu mikit verk sveit lýkr vanalega í sprinti, notat til at ráðgera hversu mikit taka skal næst. Þat er eigi einkunn fyrir hversu mjök menn strita.","also":["velocity","team velocity","hraði sveitar"]},{"id":"capacity","g":"agile","word":"Afkastageta","text":"Hversu mikit verk sveitin getr tekit á sik á tímabili, eftir frí ok önnur störf.","noTip":1},{"id":"burndown","g":"agile","word":"Niðurbrennslurit","text":"Rit yfir verk er eftir er í sprinti, minnkandi dag frá degi. Ef línan stendr flöt er eitthvat fast.","also":["burndown","burn-down chart","Burndown chart","niðurbrennslurit"]},{"id":"burnup","g":"agile","word":"Uppbrennslurit","text":"Rit yfir lokit verk vaxandi yfir tíma, við hlið heildar áætlunar, svá at sjá megi hvenær markinu er náð.","also":["burnup","burn-up chart","Burnup chart","uppbrennslurit"]},{"id":"kanbanboard","g":"agile","word":"Kanban-borð","text":"Borðit sjálft: einn dálkr fyrir hvert stig verks, með spjöldum er flytjask yfir.","also":["Kanban board","Kanban boards","Kanban-borð"]},{"id":"pullsys","g":"agile","word":"Dráttarkerfi","text":"Háttr þar sem nýtt verk hefst aðeins er einhver hefir rúm til at taka þat, í stað þess at því sé hlaðit á fullan disk.","also":["Pull system","pull-based","dráttarkerfi"]},{"id":"flow","g":"agile","word":"Streymi","text":"Hversu liðugt verk flyzt yfir borðit. Gott streymi merkir at spjöld haldi áfram, en hlaðisk eigi upp.","also":["Flow","flow of work","streymi"],"noTip":1},{"id":"leadtime","g":"agile","word":"Biðtími","text":"Hversu lengi líðr frá því er einhver biðr um eitthvat unz því er lokit.","also":["Lead time","lead times","biðtími"]},{"id":"cycletime","g":"agile","word":"Verktími","text":"Hversu lengi spjald tekr frá því er vinna hefst í raun unz því er lokit.","also":["Cycle time","cycle times","verktími"]},{"id":"throughput","g":"agile","word":"Afköst","text":"Hversu mörg spjöld er lokit á viku, eða á hverjum ákveðnum tíma.","also":["Throughput","throughput rate","afköst"]},{"id":"bottleneck","g":"agile","word":"Flöskuháls","text":"Þat eina stig er verk hleðsk upp á ok tefr allt er á eftir kemr, sem mjór háls á flösku.","also":["Bottleneck","bottlenecks","flöskuháls"]},{"id":"swimlane","g":"agile","word":"Sundrein","text":"Röð þvert yfir borðit er flokkar spjöld af einni tegund, svá sem brýnt verk eða spjöld einnar sveitar.","also":["Swimlane","swimlanes","swim lane","sundrein"]},{"id":"lean","g":"agile","word":"Lean (hagkvæmr háttr)","text":"Háttr sem sker burt sóun (allt sem hjálpar eigi kaupanda) ok heldr verki á hreyfingu."},{"id":"waste","g":"agile","word":"Sóun","text":"Í Lean, allt sem kostar fyrirhöfn en hjálpar eigi kaupanda, svá sem bið, endrtekin vinna eða at smíða hluti er enginn notar.","noTip":1},{"id":"kaizen","g":"agile","word":"Sífelld bót","text":"At verða æ lítit betri með smáum föstum breytingum, ok kanna síðan hvárt þær hjálpuðu. Endrlit er ein leið til þess. Kallat einnig kaizen.","also":["Continuous improvement","kaizen","sífelld bót"]},{"id":"selforg","g":"agile","word":"Sjálfstýrð sveit","text":"Sveit er sjálf ræðr hvernig hon vinnr verkit, í stað þess at henni sé sagt fyrir skref fyrir skref.","also":["Self-organising team","self-organising","self-managing team","sjálfstýrð sveit"]},{"id":"crossfunc","g":"agile","word":"Fjölhæf sveit","text":"Sveit sem hefir alla þá kunnáttu er hon þarf til at ljúka verkinu sjálf, svá sem hönnun, smíð ok prófun.","also":["Cross-functional team","cross-functional","fjölhæf sveit"]},{"id":"spike","g":"agile","word":"Rannsóknarsprettr","text":"Stutt rannsókn innan tímaramma til at svara spurningu áðr en hafizk er handa um raunverulegt verk.","also":["Spike","spikes","rannsóknarsprettr"]},{"id":"rework","g":"agile","word":"Endrvinna","text":"At vinna verk aftr af því at þat var eigi rétt í fyrsta sinn.","also":["rework","reworked","endrvinna"]},{"id":"safe","g":"agile","word":"Stækkuð Agile (SAFe)","text":"Hættir at nota Agile í mörgum sveitum í stórri stofnun. SAFe (Scaled Agile Framework) er eitt kunnugt dæmi.","also":["scaled Agile","stækkuð Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Mappa verks með kóða þess ok allri sögu commits. Hon má vera í tölvu þinni, á GitHub, eða hvárttveggja.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Sérstök starfslína í kóðanum, svá at breyta megi án at snerta aðalgerðina.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Vistuð ljósmynd kóðans, með stuttri athugasemd um hvat breyttisk. Þú getr ávallt snúit aftr til einnar.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"At senda vistaðar ljósmyndir (commits) úr þessari tölvu í sameiginlegt afrit á netinu, svá sem GitHub, svá at þær séu varðar ok aðrir megi sækja þær."},{"id":"merge","g":"build","word":"Merge","text":"At sameina breytingar einnar greinar í aðra, oftast aftr í aðalgerðina."},{"id":"pr","g":"build","word":"Pull request","text":"Beiðni um at breytingar greinar séu kannaðar ok sameinaðar í aðalgerðina. Sumar síður kalla þetta merge request.","also":["PR","PRs","merge request","pull request"]},{"id":"refactor","g":"build","word":"Refactor","text":"At taka til í kóðanum án at breyta hvat hann gerir: smærri skrár, skýrari heiti, minni endrtekning."},{"id":"bug","g":"build","word":"Bug","text":"Eitthvat er eigi starfar sem skyldi.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Jafningjaskoðun","text":"Annat augnapar: einhverr annarr en höfundrinn kannar verkit áðr en þat kemr til þín, svá at færri mistök komisk í gegnum. Í AI-gile kannar önnur gervigreind hvert spjald.","also":["jafningjaskoðunar","kóðaskoðun","peer review","code review"]},{"id":"code","g":"build","word":"Kóði","text":"Ritaðar fyrirskipanir er segja tölvu hvat hon skal gera. Kallat einnig frumkóði (source code).","also":["code","source code","kóði"],"noTip":1},{"id":"proglang","g":"build","word":"Forritunarmál","text":"Mál til at rita kóða, svá sem JavaScript, Python eða Java. Ýmis henta ýmsum verkum.","also":["programming language","programming languages","forritunarmál"]},{"id":"developer","g":"build","word":"Smiðr (dev)","text":"Sá er ritar ok breytir kóða. Kallaðr einnig forritari eða hugbúnaðarverkfræðingr.","also":["developer","developers","programmer","programmers","software engineer","smiðr"]},{"id":"software","g":"build","word":"Hugbúnaðr","text":"Forrit er starfa á tölvum ok símum, öndvert við vélarnar sjálfar (vélbúnaðinn).","noTip":1},{"id":"app","g":"build","word":"Forrit (app)","text":"Stytting á application: forrit er menn nota til at koma einhverju af, í síma, tölvu eða vafra.","also":["app","apps","application","applications","forrit"],"noTip":1},{"id":"webapp","g":"build","word":"Vefforrit","text":"Forrit er starfar í vafra, svá at ekkert þarf at setja upp.","also":["web app","web apps","web application","vefforrit"]},{"id":"frontend","g":"build","word":"Framhlið","text":"Sá hluti forrits er þú sér ok smellir á: skjáir, hnappar ok orð, oft í vafranum þínum.","also":["front end","front-end","frontend","framhlið"]},{"id":"backend","g":"build","word":"Bakhlið","text":"Sá hluti forrits er starfar bak við tjöldin, geymir gögnin ok vinnr verkit er þú smellir á eitthvat, svá sem at kanna lykilorð þitt.","also":["back end","back-end","backend","bakhlið"]},{"id":"fullstack","g":"build","word":"Full stack (öll lög)","text":"At vinna bæði við framhlið ok bakhlið.","also":["Full stack","full-stack","öll lög"]},{"id":"ui","g":"build","word":"Notendaviðmót (UI)","text":"Þat er maðr sér ok notar á skjá: útlit, hnappar, valmyndir ok texti.","also":["UI","user interface","notendaviðmót"]},{"id":"ux","g":"build","word":"Reynsla notanda (UX)","text":"Hvernig er at nota eitthvat: auðvelt, skýrt ok þægilegt, eða ruglandi ok seinlegt.","also":["UX","user experience","reynsla notanda"]},{"id":"accessibility","g":"build","word":"Aðgengi (a11y)","text":"At gera hluti nothæfa öllum, einnig þeim er sjá illa, geta eigi notað mús eða nota skjálesara.","also":["a11y","accessibility","aðgengi"]},{"id":"responsive","g":"build","word":"Aðlagandi hönnun","text":"At gera síður er falla ok starfa vel á hverri skjástærð, frá síma til stórs skjás.","also":["Responsive design","aðlagandi hönnun"]},{"id":"designsys","g":"build","word":"Hönnunarkerfi","text":"Sameiginlegt safn lita, leturs, hnappa ok reglna, svá at hver skjár líti út ok hegði sér á sama hátt.","also":["Design system","design systems","hönnunarkerfi"]},{"id":"architecture","g":"build","word":"Byggingarskipan","text":"Heildarlögun kerfis: hverjir eru aðalhlutirnir ok hvernig þeir tala hverr við annan."},{"id":"database","g":"build","word":"Gagnagrunnr (DB)","text":"Skipulögð geymsla upplýsinga, líkt sem mjök öflugt töflureikniskjal er forrit má lesa ok breyta.","also":["database","databases","DB","gagnagrunnr"]},{"id":"schema","g":"build","word":"Gagnagrunnsskipan","text":"Útlit gagnagrunns: hverjar töflur upplýsinga hann hefir ok hvat fer í hverja.","also":["Database schema","schema","gagnagrunnsskipan"]},{"id":"sql","g":"build","word":"SQL","text":"Stytting á structured query language: málit er notat til at biðja marga gagnagrunna um upplýsingar eða breyta þeim.","also":["SQL","Structured Query Language"]},{"id":"data","g":"build","word":"Gögn","text":"Upplýsingar sem tölva geymir, svá sem nöfn, pantanir eða stillingar.","also":["data","dataset","datasets","gögn"],"noTip":1},{"id":"server","g":"build","word":"Þjónn","text":"Tölva sem er æ kveikt ok svarar beiðnum frá öðrum tölvum, svá sem at senda vefsíðu er þú heimsækir hana.","also":["server","servers","þjónn","þjónar"]},{"id":"client","g":"build","word":"Biðlari","text":"Sá aðili er biðr um eitthvat, oftast vafri þinn eða forrit, er talar við þjón. Í viðskiptum merkir þat einnig kaupanda.","also":["client","clients","biðlari"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Stytting á application programming interface: fastr matseðill beiðna er eitt forrit má gera til annars, svá sem at biðja veðurþjónustu um spá dagsins.","also":["API","APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endapunktr","text":"Einn liðr á matseðli API: vefslóð er forrit má kalla á til at sækja eða senda eitthvat.","also":["endpoint","endpoints","endapunktr"]},{"id":"integration","g":"build","word":"Samþætting","text":"At tengja tvö kerfi svá at þau vinni saman, svá sem at búð þín sendi pantanir í reikningshugbúnað þinn.","also":["integration","integrations","samþætting"]},{"id":"webhook","g":"build","word":"Vefkrókr","text":"Boð er eitt kerfi sendir sjálfkrafa til annars þegar eitthvat gerisk, svá sem „greiðsla móttekin“.","also":["webhook","webhooks","vefkrókr"]},{"id":"library","g":"build","word":"Safn","text":"Tilbúinn kóði er annarr hefir ritat, er þú mátt nota aftr í stað þess at rita hann sjálfr.","also":["library","libraries","kóðasafn","safn"],"noTip":1},{"id":"framework","g":"build","word":"Rammi","text":"Tilbúin skipan til at smíða forrit á, sem ræðr miklu um hvernig kóðinn er lagðr, líkt sem húsgrind er þú fyllir út.","also":["framework","frameworks","rammi"]},{"id":"sdk","g":"build","word":"Hugbúnaðarsmíðakista (SDK)","text":"Kista verkfæra, kóða ok dæma til at smíða hugbúnað fyrir einn vettvang eða eina þjónustu.","also":["SDK","SDKs","software development kit","smíðakista"]},{"id":"softdep","g":"build","word":"Hugbúnaðarháðleiki","text":"Safn eða verkfæri er kóði þinn þarf til at starfa. Mikilvægt er at halda þeim nýjum vegna öryggis.","also":["Software dependency","software dependencies","hugbúnaðarháðleiki"]},{"id":"package","g":"build","word":"Pakki","text":"Knippi tilbúins kóða er þú getr sett upp ok notat í verki.","also":["package","packages","pakki"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Pakkastjóri","text":"Verkfæri er sækir ok uppfærir pakka þá er kóði þinn treystir á. npm er eitt algengt.","also":["Package manager","package managers","npm","pakkastjóri"]},{"id":"git","g":"build","word":"Git","text":"Algengasta verkfæri til at geyma sögu kóðabreytinga, sem commits ok branches."},{"id":"github","g":"build","word":"GitHub","text":"Vefsíða er geymir Git-gagnahirzlur á netinu, svá at sveitir megi deila kóða, skoða breytingar ok fylgja verki."},{"id":"vcs","g":"build","word":"Útgáfustjórn","text":"At geyma alla sögu hverrar breytingar á skrám, svá at sjá megi hverr breytti hverju ok fara aftr ef þarf. Git gerir þetta.","also":["Version control","source control","version control system","útgáfustjórn"]},{"id":"clone","g":"build","word":"Afrit (clone)","text":"At gera þitt eigit fullt afrit gagnahirzlu, með sögu hennar, í tölvu þinni.","also":["Clone","cloned","cloning","afrit"]},{"id":"pull","g":"build","word":"Sækja (pull)","text":"At sækja nýjustu commits úr sameiginlegu afriti (svá sem GitHub) í tölvu þína. Andstæða push.","also":["Pull","git pull","sækja"],"noTip":1},{"id":"mainbranch","g":"build","word":"Aðalgrein","text":"Opinber gerð kóðans er allir vinna út frá, oft kölluð main eða master.","also":["Main branch","master branch","aðalgrein"]},{"id":"conflict","g":"build","word":"Samrunaárekstr","text":"Er tvær breytingar snerta sömu línur á ólíkan hátt, svá at tölvan má eigi sameina þær ok maðr verðr at velja.","also":["Merge conflict","merge conflicts","samrunaárekstr"]},{"id":"diff","g":"build","word":"Munr (diff)","text":"Sýn er sýnir nákvæmlega hvat breyttisk milli tveggja gerða: línur bættar við ok línur teknar burt.","also":["Diff","diffs","munr"]},{"id":"fork","g":"build","word":"Kvísl (fork)","text":"Þitt eigit afrit gagnahirzlu annars, er þú mátt breyta án þess at hafa áhrif á hans.","also":["Fork","forks","forked","kvísl"]},{"id":"script","g":"build","word":"Skriftarforrit (script)","text":"Stutt forrit er vinnr eitt verk sjálft, svá sem at laga skrár eða ræsa forrit.","also":["Script","scripts","skriftarforrit"],"noTip":1},{"id":"build","g":"build","word":"Smíð (build)","text":"At breyta kóða í þat er búit er til keyrslu, eða hinn tilbúna árangr sjálfan.","also":["Build","builds","smíð"],"noTip":1},{"id":"compile","g":"build","word":"Þýða (compile)","text":"At þýða kóða er menn ritu í þat form er tölva má keyra beint.","also":["Compile","compiler","þýða"]},{"id":"cli","g":"build","word":"Skipanalína (CLI)","text":"Textagluggi þar sem þú ritar fyrirskipanir til tölvunnar í stað þess at smella. Kallat einnig terminal.","also":["Command line","command-line","CLI","terminal","skipanalína"]},{"id":"config","g":"build","word":"Stillingar (config)","text":"Stillingar er stýra hvernig hugbúnaðr hegðar sér, geymdar aðskildar frá kóðanum svá at auðvelt sé at breyta þeim.","also":["Configuration","config","configuration","stillingar"],"noTip":1},{"id":"envvar","g":"build","word":"Umhverfisbreyta","text":"Stilling er forriti er fengin þá er þat hefst, oft notuð fyrir slóðir eða lykilorð svá at þau séu eigi rituð í kóðann.","also":["Environment variable","environment variables","env var","umhverfisbreyta"]},{"id":"debugging","g":"build","word":"Villuleit","text":"At leita hví eitthvat starfar eigi, ok laga þat.","also":["Debugging","debug","debugged","villuleit"]},{"id":"pairing","g":"build","word":"Paraforritun","text":"Tveir menn (eða maðr ok gervigreind) vinna saman at sama kóða, einn ritar en annarr kannar.","also":["Pair programming","pairing","paraforritun"]},{"id":"docs","g":"build","word":"Skjöl (docs)","text":"Rituð skýring á því hvernig eitthvat starfar eða hvernig skal nota þat.","also":["Documentation","documentation","docs","skjöl"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Fyrsta skrá at lesa í gagnahirzlu: hvat verkit er ok hvernig koma skal því af stað.","also":["README","READMEs","lesmig"]},{"id":"legacy","g":"build","word":"Fornt kerfi","text":"Eldra kerfi er enn er í notkun en erfitt er at breyta, oft af því at fáir skilja þat nú.","also":["Legacy system","legacy systems","legacy code","fornt kerfi"]},{"id":"techdebt","g":"build","word":"Tæknilegar skuldir","text":"Stuttar leiðir er spara tíma nú en tefja síðari breytingar, líkt sem lán er safnar vöxtum. Endrsmíð (refactoring) greiðir þær niðr.","also":["Technical debt","tech debt","tæknilegar skuldir"]},{"id":"test","g":"test","word":"Test","text":"Prófun á því at eitthvat starfi sem skyldi. Sum próf keyrir tölvan sjálf í hvert sinn er kóði breytisk; önnur eru þá er þú reynir lokit spjald áðr en þú samþykkir þat.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Stytting á quality assurance: allt sem gert er til at tryggja at verk sé rétt áðr en þat fer í loft. Í AI-gile merkir þat sjálfvirku prófin: er QA er rautt hefir eitthvat brugðizt, ok þat má eigi í loft unz lagat er.","also":["gæðaprófanir","gæðaprófun"]},{"id":"testpile","g":"test","word":"Prófhlaði","text":"Lokin spjöld er bíða at þú reynir þau, eitt eptir annat. Samþykk eitt eða send þat aftr með athugasemd, ok hit næsta kemr upp.","also":["prófhlaða","prófhlaðar"]},{"id":"autotest","g":"test","word":"Sjálfvirkt próf","text":"Prófun er tölvan keyrir sjálf í hvert sinn er kóði breytisk, til at finna villur snemma.","also":["Automated test","automated tests","automatic tests","sjálfvirkt próf"]},{"id":"manualtest","g":"test","word":"Handprófun","text":"Maðr reynir verkit með hendi til at sjá hvárt þat hegðar sér sem skyldi.","also":["Manual test","manual tests","manual testing","handprófun"]},{"id":"unittest","g":"test","word":"Einingarpróf","text":"Lítil sjálfvirk prófun á einum örsmáum hluta kóða einum sér.","also":["Unit test","unit tests","einingarpróf"]},{"id":"integtest","g":"test","word":"Samþættingarpróf","text":"Prófun á því at margir hlutir starfi rétt saman, eigi aðeins einn í senn.","also":["Integration test","integration tests","samþættingarpróf"]},{"id":"endtoend","g":"test","word":"Próf frá enda til enda (E2E)","text":"Próf er hegðar sér sem raunverulegr notandi frá upphafi til enda, svá sem at skrá sik, kaupa ok greiða.","also":["E2E","end-to-end tests","próf frá enda til enda"]},{"id":"uat","g":"test","word":"Samþykkisprófun notanda (UAT)","text":"Þeir er báðu um verkit reyna þat sjálfir ok segja hvárt þat gerir þat er þeir þurfa. Prófahrúga AI-gile er útgáfa AI-gile af þessu.","also":["UAT","acceptance testing","samþykkisprófun"]},{"id":"regression","g":"test","word":"Afturför","text":"Þat er áðr starfaði en brotnaði eftir breytingu. Afturfararpróf kanna hvárt gamlir hlutir starfi enn.","also":["Regression","regressions","regression test","regression tests","regression testing","afturför"]},{"id":"smoke","g":"test","word":"Reykpróf","text":"Mjök skjót prófun á því at aðalatriði starfi yfirleitt, til dæmis rétt eftir at breyting fer í loft. Ef hon fellr, stöðva ok líta á.","also":["Smoke test","smoke tests","reykpróf"]},{"id":"exploratory","g":"test","word":"Könnunarprófun","text":"At reyna vöruna frjálslega ok þreifa á henni á ýmsa vegu, til at finna vandamál er áætluð próf myndu missa.","also":["Exploratory testing","exploratory test","exploratory tests","könnunarprófun"]},{"id":"testcase","g":"test","word":"Próftilfelli","text":"Ein rituð atburðarás til at reyna: skrefin, ok hvat á at gerask.","also":["Test case","test cases","próftilfelli"]},{"id":"coverage","g":"test","word":"Prófaþekja","text":"Hversu mikill hluti kóða er kannaðr af sjálfvirkum prófum. Meira er oftast öruggara, en há þekja ein sannar eigi at kóðinn starfi vel.","also":["Test coverage","code coverage","prófaþekja"]},{"id":"testdata","g":"test","word":"Prófagögn","text":"Tilbúnar dæmaupplýsingar notaðar við prófun, svá at einkaupplýsingar engis raunverulegs manns komi í ljós.","also":["Test data","test fixtures","prófagögn"]},{"id":"edgecase","g":"test","word":"Jaðartilfelli","text":"Óvenjulegt ástand á mörkunum, svá sem tómt eyðublað eða nafn með ávarpsstriki, þar sem oft bilar.","also":["Edge case","edge cases","jaðartilfelli"]},{"id":"happypath","g":"test","word":"Heillavegr","text":"Hin venjulega leið þar sem allt gengr vel. Góð prófun reynir einnig óhappaleiðir."},{"id":"perftest","g":"test","word":"Afkastaprófun","text":"At kanna hversu fljótt eitthvat er ok hversu vel þat þolir álag.","also":["Performance testing","performance test","performance tests","afkastaprófun"]},{"id":"loadtest","g":"test","word":"Álagsprófun","text":"At kanna hvernig kerfi þolir þá er margir nota þat í senn.","also":["Load testing","load test","load tests","álagsprófun"]},{"id":"sectest","g":"test","word":"Öryggisprófun","text":"At leita veikleika er gætu látit einhvern misnota kerfi eða sjá þat er hann skyldi eigi sjá.","also":["Security testing","security test","security tests","öryggisprófun"]},{"id":"accesstest","g":"test","word":"Aðgengisprófun","text":"At kanna at menn með ólíka hæfni megi nota vöruna, einnig með skjálesara eða aðeins lyklaborð.","also":["Accessibility testing","accessibility test","aðgengisprófun"]},{"id":"linting","g":"test","word":"Lint-skoðun","text":"Sjálfvirk skoðun er finnr líklegar villur ok óhreinan stíl í kóða, líkt sem stafsetningarskoðari fyrir forrit.","also":["Linting","linter","lint","lint-skoðun"]},{"id":"static","g":"test","word":"Kyrrstöðugreining","text":"At leita vandamála í kóða með því at lesa hann sjálfvirkt, án þess at keyra hann.","also":["Static analysis","static code analysis","kyrrstöðugreining"]},{"id":"flaky","g":"test","word":"Óstöðugt próf","text":"Próf er stundum stenzt en stundum fellr án skýrrar ástæðu, svá at eigi má treysta því til fulls.","also":["Flaky test","flaky tests","óstöðugt próf"]},{"id":"repro","g":"test","word":"Endrgera (repro)","text":"At láta bug gerask aftr af ásettu ráði með því at fylgja sömu skrefum, svá at rannsaka megi hann ok laga. At rita þau skref er gagnligasti hluti bug-skýrslu.","also":["repro","reproduce","steps to reproduce","endrgera"]},{"id":"severity","g":"test","word":"Alvara","text":"Hversu slæm áhrif vandamáls eru, frá lítilli ertingu til þess at allt stöðvisk.","also":["Severity","severity level","alvara"]},{"id":"deploy","g":"change","word":"Deploy","text":"At afrita nýja gerð hugbúnaðar yfir á tölvurnar er keyra hann, svá sem prófunarafrit eða hina lifandi þjónustu."},{"id":"release","g":"change","word":"Útgáfa","text":"Nefndr böggull lokins verks er ferr í gang saman, með stuttum skýringum um hvat breyttisk. 🚀 Útgáfur rita skýringarnar af lokinum spjöldum.","also":["útgáfur","útgáfu","útgáfunnar"]},{"id":"rollback","g":"change","word":"Rúlla aftr","text":"At snúa aftr til síðustu gerðar sem starfaði þá er ný veldr vanda. Í AI-gile safnar Rúlla aftr afturköllunarskrefum, rituðum við hverja breytingu, í einn gátlista.","also":["aftrrúllun","rúllat aftr","rollback"]},{"id":"live","g":"change","word":"Í gangi","text":"Hin sanna útgáfa er menn nota, eigi afrit til at reyna hluti á. Hugbúnaðarsmiðir kalla þat ok production.","also":["fer í gang","fara í gang","production"],"noTip":1},{"id":"change","g":"change","word":"Breyting","text":"Ætluð breyting á nökkuru er menn treysta á, rituð fyrst: hvat, hví, áhættan, hvenær, ok hversu aftr taka. Hef eina með 🔀 Bera upp breytingu.","also":["breytingar","breytingu","breytingarbeiðni","breytingarbeiðnir"],"noTip":1},{"id":"risk","g":"change","word":"Áhætta","text":"Nökkut er farit gæti illa, metit eptir því hversu líklegt ok hversu illt þat yrði. ⚠️ Áhættur geyma þær í einum lista, hæsta mat fyrst, hverja með degi til at líta á aftr.","also":["áhættur","áhættu","áhættuskrá"]},{"id":"chgwin","g":"change","word":"Breytingagluggi","text":"Tímarnir er breytingar mega fara í gang, svá sem kyrrt þriðjudagskveld. Utan glugga má breytingaspjald eigi ljúkask, nema þat sé neyð.","also":["breytingagluggar","glugga","gluggi"]},{"id":"gonogo","g":"change","word":"Gakk / eigi gakk","text":"Síðasta athugun rétt áðr en breyting fer í loft: hverr sá er samþykkja skal segir Gakk eða Eigi gakk. Þat heldr aðeins áfram er allir segja Gakk.","also":["go/no go","go-no-go","gakk/eigi gakk"]},{"id":"approval","g":"change","word":"Samþykki","text":"At bíða já áðr en verk hefsk. Spjald er vinr berr upp, eða breyting, bíðr í ✅ Samþykki unz þú samþykkir eða hafnar því.","also":["samþykkis","samþykkja"]},{"id":"quiettime","g":"change","word":"Kyrr tími","text":"Tími, svá sem meðan á beinni útsendingu stendr, sýningu eða um nótt, er ekkert fer í loft. Sveitirnar halda áfram at vinna ok prófa, en útsetning bíðr unz honum lýkr. Annars staðar kallat breytingafrost (change freeze).","also":["kyrrir tímar","kyrrum tíma","breytingafrost"]},{"id":"devops","g":"change","word":"DevOps","text":"Vinnuháttr þar sem þeir er smíða hugbúnað ok þeir er reka hann vinna sem ein sveit, með mikilli sjálfvirkni, svá at breytingar fari oft ok örugglega í loft."},{"id":"cicd","g":"change","word":"CI/CD (sífelld samþætting ok afhending)","text":"Breytingar allra eru oft sameinaðar í aðalgerðina ok kannaðar sjálfvirkt í hvert sinn (sífelld samþætting), svá at hugbúnaðr sé æ búinn til at fara í loft með einum hnapp (sífelld afhending).","also":["CI/CD","CI","CD","continuous integration","continuous delivery","sífelld samþætting"]},{"id":"contdeploy","g":"change","word":"Sífelld útsetning","text":"Einu skrefi lengra en sífelld afhending: hver breyting er stenzt prófin fer sjálfkrafa í loft, án hnapps til at þrýsta á.","also":["Continuous deployment","continuous deployments","sífelld útsetning"]},{"id":"pipeline","g":"change","word":"Leiðsla","text":"Sjálfvirk röð skrefa er breyting fer um á leið sinni í loft, svá sem smíð, prófun, síðan útsetning.","also":["Pipeline","pipelines","leiðsla"]},{"id":"environment","g":"change","word":"Umhverfi","text":"Eitt aðskilit afrit kerfis til eins hlutverks, svá sem eitt til at smíða í, eitt til at prófa í ok hit lifandi.","also":["Environment","environments","umhverfi"],"noTip":1},{"id":"devenv","g":"change","word":"Smíðaumhverfi","text":"Afrit þat er smiðr vinnr í, oft í hans eigin tölvu, þar sem ekkert tjón verðr þótt eitthvat brotni.","also":["Development environment","dev environment","smíðaumhverfi"]},{"id":"testenv","g":"change","word":"Prófaumhverfi","text":"Aðskilit afrit kerfis notat aðeins til prófana, svá at hin raunverulega þjónusta sé eigi snert.","also":["Test environment","test environments","prófaumhverfi"]},{"id":"staging","g":"change","word":"Æfingarsvið","text":"Síðasta afrit, sett upp líkt hinu lifandi, til lokaprófunar áðr en breyting fer í loft.","also":["Staging","staging environment","æfingarsvið"]},{"id":"artifact","g":"change","word":"Smíðarafurð","text":"Skrá eða knippi er smíð skilar, búit til geymslu, könnunar eða útsetningar.","also":["Build artifact","build artifacts","smíðarafurð"]},{"id":"hotfix","g":"change","word":"Neyðarlagfæring","text":"Brýn lagfæring send skjótt í loft utan venjulegrar áætlunar, af því at eitthvat mikilvægt er brotit.","also":["Hotfix","hotfixes","neyðarlagfæring"]},{"id":"patch","g":"change","word":"Bót","text":"Lítil uppfærsla er lagar bug eða lokar öryggisgati. Mikilvægt er at nota öryggisbætr skjótt.","also":["Patch","patches","security patch","security patches","bót"]},{"id":"version","g":"change","word":"Útgáfunúmer","text":"Merki svá sem 2.4.1 er segir hverja útgáfu þú hefir. Oft breytisk fyrsta talan við stórar breytingar en síðasta við smáar lagfæringar.","also":["Version number","version numbers","semantic versioning","útgáfunúmer"]},{"id":"relnotes","g":"change","word":"Útgáfuskýringar","text":"Stuttr einfaldr listi yfir hvat breyttisk í útgáfu, fyrir þá er nota hana, með lagfæringum ok þekktum takmörkum. Kallat einnig changelog.","also":["Release notes","changelog","change log","útgáfuskýringar"]},{"id":"flag","g":"change","word":"Eiginleikarofi","text":"Rofi til at kveikja ok slökkva á eiginleika, svá at nýtt verk megi fara í loft falit ok vera kveikt (eða slökkt aftr) án nýrrar útgáfu.","also":["Feature flag","feature flags","feature toggle","feature toggles","eiginleikarofi"]},{"id":"rollfwd","g":"change","word":"Fara fram á við","text":"At laga slæma útgáfu með því at gefa skjótt út nýja, leiðrétta gerð í stað þess at snúa aftr til hinnar gömlu.","also":["Roll forward","rolling forward","rolled forward","fara fram á við"]},{"id":"canary","g":"change","word":"Kanarífuglsútgáfa","text":"At setja breytingu fyrst í loft fyrir lítinn hóp, en fyrir alla aðeins er hon sýnisk góð. Nefnd eftir kanarífuglum er námumenn höfðu niðr í jörð sem fyrstu viðvörun.","also":["Canary release","canary releases","canary","kanarífuglsútgáfa"]},{"id":"bluegreen","g":"change","word":"Blá-græn útsetning","text":"At hafa tvö afrit hins lifandi kerfis ok flytja menn í einu yfir á hit nýja, svá at skjótt megi snúa aftr ef illa fer.","also":["Blue-green deployment","blue-green","blue green deployment","blá-græn útsetning"]},{"id":"zerodown","g":"change","word":"Útsetning án hlés","text":"At setja nýja gerð í loft án þess at þjónustan stöðvisk nokkurn tíma fyrir notendr.","also":["Zero-downtime deployment","zero downtime","zero-downtime","útsetning án hlés"]},{"id":"chgenable","g":"change","word":"Breytingastjórn","text":"At hjálpa breytingum at takast: vega áhættu, fá rétt samþykki ok velja góðan tíma. Kallat einnig change management.","also":["Change enablement","change management","breytingastjórn"]},{"id":"cab","g":"change","word":"Ráðgjafaráð breytinga (CAB)","text":"Hópr er lítr á mikilvægar breytingar ok verðr ásáttr um hvárt ok hvenær þær megi fram ganga.","also":["CAB","change advisory board","ráðgjafaráð breytinga"]},{"id":"stdchange","g":"change","word":"Stöðluð breyting","text":"Áhættulítil breyting gerð á sama reynda hátt í hvert sinn, svá at hon er samþykkt fyrirfram.","also":["Standard change","standard changes","stöðluð breyting"]},{"id":"normchange","g":"change","word":"Venjuleg breyting","text":"Breyting sem verðr at kanna ok samþykkja áðr en hon fer fram.","also":["Normal change","normal changes","venjuleg breyting"]},{"id":"emergchange","g":"change","word":"Neyðarbreyting","text":"Breyting sem verðr at gerask þegar í stað til at laga eða afstýra alvarlegum vanda, með skjótara samþykki eftir því.","also":["Emergency change","emergency changes","neyðarbreyting"]},{"id":"automation","g":"change","word":"Sjálfvirkni","text":"At láta tölvuna vinna endrtekit verk sjálfa, svá at þat sé skjótara ok gert á sama hátt í hvert sinn.","also":["Automation","automated","sjálfvirkni"],"noTip":1},{"id":"infra","g":"change","word":"Undirstöður","text":"Vélarnar, netin ok þjónusturnar er hugbúnaðr starfar á.","also":["Infrastructure","infra","undirstöður"]},{"id":"iac","g":"change","word":"Undirstöður sem kóði (IaC)","text":"At lýsa þjónum þínum ok stillingum í skrám geymdum með kóðanum, svá at endrsmíða megi þær á nákvæmlega sama hátt í hvert sinn.","also":["IaC","Infrastructure as code","undirstöður sem kóði"]},{"id":"cloud","g":"change","word":"Ský","text":"At leigja tölvur, geymslu ok þjónustur af stórum veitanda um netit, í stað þess at eiga vélarnar sjálfr.","also":["Cloud","the cloud","cloud computing","ský"]},{"id":"provider","g":"change","word":"Skýveitandi","text":"Fyrirtæki er leigir út tölvuafl um netit, svá sem Amazon Web Services (AWS), Microsoft Azure eða Google Cloud.","also":["Cloud provider","cloud providers","skýveitandi"]},{"id":"hosting","g":"change","word":"Hýsing","text":"Sá staðr er forrit þitt eða vefsíða býr ok starfar, svá at menn nái til þess, oftast leigðr af fyrirtæki.","also":["Hosting","hýsing"]},{"id":"domain","g":"change","word":"Lénsheiti","text":"Vefslóðin er menn rita, svá sem example.com. Hún er leigð til árs í senn, svá at endrnýja verðr hana.","also":["Domain name","domain names","domain","lénsheiti"]},{"id":"dns","g":"change","word":"DNS","text":"Stytting á domain name system: heimilisfangaskrá netsins, er breytir nafni svá sem example.com í heimilisfang réttrar tölvu.","also":["DNS","domain name system","lénakerfi"]},{"id":"container","g":"change","word":"Ílát","text":"Lokaðr pakki er geymir forrit ok allt sem þat þarf, svá at þat starfi eins á hverri tölvu. Docker er kunnasta verkfærit.","also":["Container","containers","Docker","ílát"],"noTip":1},{"id":"vm","g":"change","word":"Sýndarvél (VM)","text":"Gervitölva er starfar inni í raunverulegri, svá at ein stór vél megi verka sem margar.","also":["VM","VMs","virtual machines","sýndarvél"]},{"id":"serverless","g":"change","word":"Þjónalaust","text":"At keyra kóða án þess at annast nokkra þjóna sjálfr: veitandinn keyrir hann þá er þarf ok þú greiðir aðeins fyrir þat er þú notar."},{"id":"lb","g":"change","word":"Álagsjafnari","text":"Hlutr sem skiptir gestum á marga þjóna, svá at enginn einn ofhlaðisk.","also":["Load balancer","load balancers","álagsjafnari"]},{"id":"cache","g":"change","word":"Skyndiminni","text":"Hentug geymsla nýlegra niðrstaðna höfð nærri, svá at sama hlut þurfi eigi at sækja eða reikna aftr. At tæma hana getr lagat síður er virðask úreltar.","also":["Cache","caches","caching","cached","skyndiminni"]},{"id":"cdn","g":"change","word":"Efnisdreifinet (CDN)","text":"Heimsvítt safn þjóna er geyma afrit síðna þinna ok mynda nærri gestum, svá at þær hlaðisk skjótt.","also":["CDN","content delivery network","efnisdreifinet"]},{"id":"migration","g":"change","word":"Flutningr","text":"At flytja gögn eða kerfi úr gamalli uppsetningu í nýja, eða breyta gætilega lögun gagnagrunns.","also":["Migration","migrations","database migration","flutningr"]},{"id":"service","g":"run","word":"Þjónusta","text":"Nökkut er þú smíðaðir ok menn treysta á, svá sem vefsetr eða forrit, er gætt er svá at þat virki áfram. Merk við „Þetta verkefni er þjónusta“ ok seg hvat hon býðr, hverr hana notar ok hverr er á vakt.","also":["þjónustur","þjónustu","þjónustunnar"]},{"id":"uptimepct","g":"run","word":"Uppitími","text":"Hversu mikinn hluta tímans þjónusta starfar, oftast sem hundraðshluta. 99,9% leyfir enn um 43 mínútur niðri á mánuði.","also":["Uptime","uptime percentage","uppitími"]},{"id":"uptime","g":"run","word":"Uppitímaathugun","text":"Sjálfvirk athugun, á fárra mínútna fresti, at þjónusta þín svari enn. Ef hon bregzk mörgum sinnum í röð, opnar AI-gile atviksspjald af sjálfu sér.","also":["uptime checks","uppitímaathuganir","uptime"]},{"id":"statuspage","g":"run","word":"Stöðusíða","text":"Opinber síða er sýnir hvárt þjónusta virki (grænt, rauðgult eða rautt) með hinum nýjustu tíðindum, svá at þeir er nota hana megi líta á í stað þess at spyrja.","also":["stöðusíður","stöðusíðu","stöðusíðunni"]},{"id":"desk","g":"run","word":"Þjónustuborð","text":"Þar er spurningar ok tilkynningar koma inn frá þeim er nota þjónustu þína. AI-gile flokkar hverja sem beiðni, atvik eða hugmynd, ok segir til ef hon líkisk nökkuru er áðr var tilkynnt.","also":["þjónustuborð","hjálparborð","helpdesk"]},{"id":"svcrequest","g":"run","word":"Þjónustubeiðni","text":"Einhverr biðr um nökkut hversdagsligt, svá sem nýjan reikning eða litla hjálp, en tilkynnir eigi at nökkut sé brotit. Hon bíðr síns tíma; atvik gengr fyrst.","also":["þjónustubeiðnir"]},{"id":"incident","g":"run","word":"Atvik","text":"Eitthvat sem er brotit eða starfar eigi rétt fyrir þá er nota þat nú, svá sem at vefsíðan er niðri eða mjök seinleg. 🔥 atvikaspjald fer fram fyrir röðina: at koma því aftr í gang kemr fyrst.","also":["atviki","atviks","atvikum","atviksspjald"]},{"id":"major","g":"run","word":"Stórt atvik","text":"Mikit atvik: margir menn snortnir, eða fé eða gögn í hættu. Einn hnappr setr hverja sveit á þat (sveimr), vekr þann er á vakt er ok biðr um stöðufregn á hverjum 30 mínútum.","also":["stór atvik","stóru atviki"]},{"id":"oncall","g":"run","word":"Vakt","text":"At vera sá er svarar þá er nökkut brotnar, jafnvel um nótt. Hver þjónusta hefir sveitarmann á vakt er vakinn er fyrst við atvik hennar.","also":["á vakt","vaktmaðr","vaktar","on-call"]},{"id":"replyby","g":"run","word":"Svarfrestr","text":"Hversu lengi spjald má bíða fyrsta svars, t.d. eina stund fyrir atvik. Eptir þat fær þat rauða klukku, svá at ekkert gleymisk í kyrrþey. Kallask ok svarmark.","also":["svarfrest","svarfrestir","svarmark"]},{"id":"postmortem","g":"run","word":"Eftirrannsókn","text":"Stutt endrlit eptir atvik: hvat gerðisk, hvat hjálpaði ok hverju skal breyta, án þess at kenna nökkurum um. Atviki má eigi loka án hennar.","also":["eftirrannsóknir","eftirrannsókn","post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Vandamál","text":"Hin hulda sök at baki eins eða fleiri atvika. 🧩 Vandamálsspjald safnar saman atvikum er koma sí ok æ aftr, svá at sökin finnisk ok lagisk um alla tíð.","also":["vandamáls","vandamálum","vandamálsspjald"],"noTip":1},{"id":"rootcause","g":"run","word":"Rótarsök","text":"Hin sanna ástæða þess at nökkut brotnaði, eigi aðeins þat er þú sátt fara illa. Laga rótarsökina, ok atvikit hættir at koma aftr.","also":["rótarsakir","rótarsakar"]},{"id":"workaround","g":"run","word":"Undankoma","text":"Leið til at halda hlutum í gangi unz hin sanna lagfæring er búin, svá sem at ræsa nökkut aftr þá er þat festisk. Hon er rituð á vandamálsspjaldit, svá at engi þurfi at finna hana aftr.","also":["undankomu","undankomur","úrræði"]},{"id":"knownerror","g":"run","word":"Kunn villa","text":"Vandamál þar sem orsökin er skilin en eigi enn lagat, oftast með ritaðri krókaleið. 🧩 Kunnar villur telr þær upp, svá at allir noti krókaleiðina í stað þess at grafa aftr.","also":["kunnar villur","kunna villu"]},{"id":"runbook","g":"run","word":"Leiðbeiningabók","text":"Skref fyrir skref leiðsögn til at laga kunna tegund vandræða, svá at þat sé gert á sama hátt, skjótt, hvert sinn. Eptir stórt atvik má sveitin leggja eina til, ok þú gefr OK.","also":["leiðbeiningabækr","leiðbeiningabókar","runbook","runbooks"]},{"id":"ci","g":"run","word":"Stillingarhlutr","text":"Einn hlutr er þjónusta þín treystir á, svá sem netþjónn, lén, skírteini, lykill eða birgir. 🗂️ Stillingarhlutir telja þá upp fyrir hverja þjónustu, svá at þú sér hvat atvik snertir ok hvat þarf endrnýjun eða afrit.","also":["stillingarhlutir"]},{"id":"expiry","g":"run","word":"Gildislok","text":"Sá dagr er eitthvat hættir at starfa nema þat sé endrnýjat, svá sem öryggisvottorð vefsíðu eða vefslóð hennar. AI-gile fylgist með þessum dögum ok gerir eitt spjald til at endrnýja hvert 30 dögum fyrr, svá at ekkert stöðvisk óvænt.","also":["lokadagar","gildistími","gætsla gildisloka"]},{"id":"backup","g":"run","word":"Afrit","text":"Vistat eintak gagna þinna frá fyrri tíð, at grípa til ef nökkut týnisk eða spillisk. AI-gile gerir afrit af töflum þínum hvern dag.","also":["afriti","afrits","afritum","backup"]},{"id":"restore","g":"run","word":"Endrheimt","text":"At setja gögn aftr af afriti. Afrit telsk eigi sannliga fyrr en þú veizt at þat má endrheimta, því er vert at reyna þat stundum.","also":["endrheimta","endrheimt","endrheimtr"]},{"id":"svcreview","g":"run","word":"Þjónustuendrskoðun","text":"Litit aftr yfir einn mánuð þjónustu: atvik opnuð ok lagfærð, hversu skjótt menn fengu svar, uppitími ok tákn notuð. Mánaðarleg endrskoðun sýnir þat fyrir hverja þjónustu.","also":["þjónustuendrskoðanir","mánaðarleg endrskoðun","mánaðarligar endrskoðanir"]},{"id":"accessreview","g":"run","word":"Aðgangsendrskoðun","text":"At kanna á 90 daga fresti hverr kemst enn inn: deilingartengla, hlutverk vina ok vistuð lykilorð ok lykla. Þú heldr hverju eða fjarlægir, svá at gamall aðgangr dveljisk eigi.","also":["aðgangsendrskoðanir"]},{"id":"improvements","g":"run","word":"Úrbótaskrá","text":"Allt er sveitin ákvað at bæta, á einum stað: tillögur úr retro, aðgerðir úr endrskoðunum ok lagfæringar vandamála, hvert með stöðu sinni. Finn hana undir 📈 Úrbætr.","also":["úrbótaskrár","úrbætr"]},{"id":"tokencap","g":"run","word":"Táknamark","text":"Mánaðarmark á táknum er erindrekar þjónustu mega nota. Við 80% fær þú viðvörun; við 100% bíðr bakgrunnsverk þeirra til næsta mánaðar eða unz þú hækkar markit.","also":["táknamörk"]},{"id":"svcmgmt","g":"run","word":"Þjónustustjórn","text":"Allt er til þarf at halda þjónustu gagnlegri ok starfandi fyrir þá er treysta henni, dag eftir dag.","also":["Service management","þjónustustjórn"]},{"id":"itil","g":"run","word":"ITIL","text":"Víða notuð leiðsögn um góða þjónustustjórn, er tekr til atvika, vandamála ok breytinga. Nafnit stóð áðr fyrir IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Stjórn upplýsingatækniþjónustu (ITSM)","text":"At reka tækni sem þjónustu fyrir menn, með skýrum háttum til at annast beiðnir, atvik, breytingar ok umbætr.","also":["ITSM","IT service management","stjórn upplýsingatækniþjónustu"]},{"id":"managed","g":"run","word":"Rekin þjónusta","text":"Þjónusta er annarr rekr ok annast fyrir þik, samkvæmt samkomulagi um hversu vel hon skal starfa.","also":["Managed service","managed services","rekin þjónusta"]},{"id":"svcowner","g":"run","word":"Þjónustuhaldari","text":"Sá er svarar fyrir þjónustu í heild: hversu vel hon starfar, hvat hon kostar ok hvernig hon batnar.","also":["Service owner","service owners","þjónustuhaldari"]},{"id":"sla","g":"run","word":"Þjónustusamningr (SLA)","text":"Rituð heit til kaupenda um hversu vel þjónusta mun starfa, svá sem „uppi 99,9% tímans“ eða „svarat innan stundar“, oft með endrgreiðslu ef hon bregzt.","also":["SLA","SLAs","service level agreement","þjónustusamningr"]},{"id":"slo","g":"run","word":"Þjónustumarkmið (SLO)","text":"Eigit mark sveitarinnar um hversu vel þjónusta skal starfa yfir tímabil, oftast sett nokkru strangara en SLA til öryggis.","also":["SLO","SLOs","service level objective","þjónustumarkmið"]},{"id":"sli","g":"run","word":"Þjónustumælir (SLI)","text":"Raunveruleg mæling er borin er við markit, svá sem hlutfall heimsókna er hlóðust vel.","also":["SLI","SLIs","service level indicator","þjónustumælir"]},{"id":"availability","g":"run","word":"Tiltækileiki","text":"Hvárt menn megi nota þjónustu þá er þeir þurfa, oft mælt sem uppitími.","also":["Availability","high availability","tiltækileiki"]},{"id":"downtime","g":"run","word":"Niðritími","text":"Tími er þjónusta starfar eigi eða er slökkt, áætlaðr eða eigi.","also":["Downtime","down time","niðritími"]},{"id":"errorbudget","g":"run","word":"Villufjárhagr","text":"Sá litli skammtr bilana er áreiðanleikamark þitt leyfir. Meðan nokkut er eftir máttu taka áhættu með breytingum; er þat er þrotit hægir þú á.","also":["Error budget","error budgets","villufjárhagr"]},{"id":"outage","g":"run","word":"Rof","text":"Tími er þjónusta er niðri eða illa biluð fyrir notendr sína.","also":["Outage","outages","rof"]},{"id":"degraded","g":"run","word":"Skert","text":"Starfar, en illa: seinlega, eða með suma hluti óstarfandi.","also":["Degraded","degraded service","skert þjónusta"]},{"id":"monitoring","g":"run","word":"Vöktun","text":"At fylgjast sjálfvirkt með þjónustu æ, svá at vandamál sjáisk, helzt áðr en notendr verða varir.","also":["Monitoring","vöktun"]},{"id":"observability","g":"run","word":"Sýnileiki kerfis","text":"Hversu vel þú getr sagt hvat gerisk inni í kerfi utan frá, með annálum þess, tölum ok slóðum.","also":["Observability","o11y","sýnileiki kerfis"]},{"id":"log","g":"run","word":"Annáll","text":"Dagbók er forrit heldr áfram um hvat þat gerir, notuð til at finna hvat fór úrskeiðis.","also":["Log","logs","logging","annáll"],"noTip":1},{"id":"trace","g":"run","word":"Slóð","text":"Skrá yfir hvernig ein beiðni fer um ýmsa hluta kerfis, skref fyrir skref, ok sýnir hvar hon tafðisk.","also":["Trace","traces","tracing","slóð"]},{"id":"latency","g":"run","word":"Töf (latency)","text":"Hversu lengi eitthvat er at svara, svá sem biðin milli smells ok þess er síðan birtisk.","also":["Latency"]},{"id":"alert","g":"run","word":"Viðvörun","text":"Sjálfvirkt boð um at eitthvat þarfnask athygli, svá sem at vefsíðan svarar eigi.","also":["Alert","alerts","alerting","viðvörun"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Viðvörunarþreyta","text":"Er svá margar viðvaranir eru at menn hætta at sinna þeim, einnig hinum mikilvægu.","also":["Alert fatigue","alarm fatigue","viðvörunarþreyta"]},{"id":"dashboard","g":"run","word":"Mælaborð","text":"Skjár er sýnir mikilvægustu tölur ok stöður í einu augnabragði.","also":["Dashboard","dashboards","mælaborð"],"noTip":1},{"id":"paging","g":"run","word":"Kall","text":"At kalla brýnt á eða vekja þann er hefir vakt vegna vandamáls.","also":["Paging","paged","kall"]},{"id":"escalation","g":"run","word":"Stigmögnun","text":"At kalla til þann er hefir meiri kunnáttu eða vald þá er vandamál verðr eigi leyst á núverandi stigi, eða eigi nógu skjótt.","also":["Escalation","escalate","escalated","stigmögnun"]},{"id":"triage","g":"run","word":"Flokkun eftir bráðleika","text":"At flokka skjótt innkomin mál eftir því hversu brýn ok mikilvæg þau eru, svá at hit versta sé fyrst sinnt.","also":["Triage","triaged","flokkun"]},{"id":"impact","g":"run","word":"Áhrif","text":"Hversu mjök eitthvat snertir menn: hversu marga, ok hversu illa.","noTip":1},{"id":"urgency","g":"run","word":"Bráðleiki","text":"Hversu skjótt þarf at sinna einhverju. Áhrif ok bráðleiki saman ráða forgangi.","noTip":1},{"id":"plevels","g":"run","word":"Forgangsstig (P1, P2…)","text":"Merki um hversu brýnt mál er. P1 er alvarlegast ok krefst aðgerðar þegar í stað.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Miðaröð","text":"Listi beiðna ok atvika er bíða þess at verða tekin.","also":["Ticket queue","ticket queues","miðaröð"]},{"id":"tiers","g":"run","word":"Fyrsta lína ok önnur lína","text":"Stig aðstoðar: fyrsta lína tekr við kallinu ok lagar einföld mál; önnur lína hefir dýpri kunnáttu fyrir hin erfiðari. Kallat einnig tier 1 ok tier 2.","also":["first-line support","tier 1","tier 2","fyrsta lína","önnur lína"]},{"id":"ic","g":"run","word":"Atvikastjóri","text":"Sá einn maðr er stýrir viðbrögðum við atviki, svá at allir viti hverr ræðr ok hverr gerir hvat.","also":["Incident commander","incident commanders","atvikastjóri"]},{"id":"responsetime","g":"run","word":"Svarstími","text":"Hversu lengi líðr áðr en einhver tekr fyrst við beiðni eða atviki.","also":["Response time","response times","svarstími"]},{"id":"resolution","g":"run","word":"Lausnartími","text":"Hversu lengi tekr at leysa beiðni eða atvik til fulls, frá tilkynning unz lagat er.","also":["Resolution time","resolution times","time to resolve","lausnartími"]},{"id":"mttr","g":"run","word":"Meðalbatatími (MTTR)","text":"At meðaltali, hversu lengi tekr at koma þjónustu aftr í gang eftir at hon bilar. MTTR getr merkt nokkuð ólíkt, svá at seg hvat þú mælir.","also":["MTTR","mean time to restore","mean time to recover","meðalbatatími"]},{"id":"mtbf","g":"run","word":"Meðaltími milli bilana (MTBF)","text":"At meðaltali, hversu lengi þjónusta starfar áðr en eitthvat bilar.","also":["MTBF","mean time between failures","meðaltími milli bilana"]},{"id":"cmdb","g":"run","word":"Stillingagrunnr (CMDB)","text":"Listi allra stillingaratriða þinna ok hvernig þau tengjask, svá at sjá megi hvat treystir á hvat.","also":["CMDB","configuration management database","stillingagrunnr"]},{"id":"asset","g":"run","word":"Eign","text":"Allt verðmætt er þú átt eða greiðir fyrir til at reka þjónustuna, svá sem fartölva, hugbúnaðarleyfi eða lén.","also":["Asset","assets","eign"],"noTip":1},{"id":"capplan","g":"run","word":"Afkastaáætlun","text":"At tryggja at nóg tölvuafl, geymsla ok menn verði fyrir þat er kemr.","also":["Capacity planning","capacity plan","afkastaáætlun"]},{"id":"scaling","g":"run","word":"Stækkun","text":"At ráða við fleiri notendr með því at gefa vél meira afl (scaling up) eða bæta við fleiri vélum (scaling out).","also":["Scaling","scale up","scale out","scaling up","scaling out","stækkun"]},{"id":"bcp","g":"run","word":"Rekstrarsamfelli","text":"Áætlanir um at halda mikilvægum hlutum gangandi er eitthvat stórt fer úrskeiðis, svá sem at missa skrifstofu, mikilvægan birgi eða tölvurnar.","also":["Business continuity","business continuity plan","rekstrarsamfelli"]},{"id":"dr","g":"run","word":"Endrheimt eftir hamfarir (DR)","text":"Áætlun ok tól til at fá þjónustu aftr eftir alvarlegt áfall, svá sem at missa heila gagnamiðstöð.","also":["Disaster recovery","DR","endrheimt eftir hamfarir"]},{"id":"rto","g":"run","word":"Batatímamark (RTO)","text":"Lengsti tími er þjónusta má vera niðri eftir áfall áðr en hon verðr at starfa aftr.","also":["RTO","recovery time objective","batatímamark"]},{"id":"rpo","g":"run","word":"Batapunktsmark (RPO)","text":"Hversu mikil nýleg gögn þú mátt missa, mælt í tíma. RPO einnar stundar merkir afrit minnst á hverri stund.","also":["RPO","recovery point objective","batapunktsmark"]},{"id":"redundancy","g":"run","word":"Vara-útbúnaðr","text":"At hafa varahluti búna, svá sem annan þjón, svá at ein bilun stöðvi eigi þjónustuna.","also":["Redundancy","vara-útbúnaðr"]},{"id":"failover","g":"run","word":"Yfirfærsla við bilun","text":"At skipta sjálfkrafa yfir á varakerfi þá er hit venjulega bilar.","also":["Failover","fail over","yfirfærsla við bilun"]},{"id":"spof","g":"run","word":"Einn bilunarpunktr","text":"Einn hlutr er dregr allt niðr með sér er hann bilar, af því at enginn varahlutr er til.","also":["Single point of failure","single points of failure","SPOF","einn bilunarpunktr"]},{"id":"maintwin","g":"run","word":"Viðhaldsgluggi","text":"Áætlaðr tími er þjónusta má vera stöðvuð eða seinleg vegna viðhalds, tilkynntr notendum fyrirfram.","also":["Maintenance window","maintenance windows","planned maintenance","viðhaldsgluggi"]},{"id":"handover","g":"run","word":"Afhending verks","text":"At fela öðrum manni eða sveit verk, vitneskju ok ábyrgð, svá at ekkert falli niðr.","also":["Handover","handovers","afhending"]},{"id":"kb","g":"run","word":"Þekkingarbanki","text":"Safn hjálpargreina ok svara, fyrir notendr ok sveitina.","also":["Knowledge base","knowledge bases","þekkingarbanki"]},{"id":"csat","g":"run","word":"Ánægja kaupenda (CSAT)","text":"Einkunn frá notendum um hversu ánægðir þeir voru, oft spurð eftir at beiðni er lokat.","also":["CSAT","customer satisfaction","ánægja kaupenda"]},{"id":"supplier","g":"run","word":"Birgir","text":"Utanaðkomandi fyrirtæki er þú treystir á, svá sem hýsingaraðili þinn. Kallat einnig vendor eða þriðji aðili.","also":["Supplier","suppliers","vendor","vendors","third party","birgir"],"noTip":1},{"id":"retire","g":"run","word":"Lok þjónustu","text":"At slökkva á þjónustu fyrir fullt ok allt á öruggan hátt: segja notendum, annast gögn hennar ok aðgang ok stöðva kostnað.","also":["Service retirement","retiring a service","lok þjónustu"]},{"id":"eol","g":"run","word":"Ævilok (EOL)","text":"Er vara fær eigi lengr uppfærslur eða aðstoð frá smið sínum, svá at skipta skal henni út.","also":["EOL","end-of-life","End of life","ævilok"]},{"id":"cybersec","g":"sec","word":"Netöryggi","text":"At verja kerfi ok gögn gegn innbroti, þjófnaði eða skemmdum.","also":["Cybersecurity","cyber security","netöryggi"]},{"id":"authn","g":"sec","word":"Auðkenning","text":"At kanna hverr einhver er, oftast með lykilorði eða kóða. Oft stytt í authn.","also":["Authentication","authn","auðkenning"]},{"id":"authz","g":"sec","word":"Heimildarkönnun","text":"At kanna hvat einhver má gera er þú veizt hverr hann er. Oft stytt í authz.","also":["Authorisation","authz","authorization","heimildarkönnun"]},{"id":"mfa","g":"sec","word":"Fjölþátta auðkenning (MFA)","text":"At skrá sik inn með tveim eða fleiri sönnunum, svá sem lykilorði ok kóða í síma. Kallat einnig tveggja þátta (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","fjölþátta auðkenning"]},{"id":"sso","g":"sec","word":"Ein innskráning (SSO)","text":"At skrá sik inn einu sinni til at komast í mörg kerfi, svá sem at nota vinnureikning sinn alls staðar.","also":["SSO","single sign-on","ein innskráning"]},{"id":"pwmgr","g":"sec","word":"Lykilorðastjóri","text":"Forrit er gerir sterk lykilorð ok man þau fyrir þik.","also":["Password manager","password managers","lykilorðastjóri"]},{"id":"secret","g":"sec","word":"Leyndarmál","text":"Lykilorð, lykill eða annarr einkakóði er forrit notar til at komast í eitthvat. Því má aldri deila né rita þat í kóðann.","also":["Secret","secrets","leyndarmál"],"noTip":1},{"id":"apikey","g":"sec","word":"API-lykill","text":"Leynikóði er leyfir forriti at nota API annarrar þjónustu, ok sýnir hverr notar (ok greiðir fyrir) hana.","also":["API key","API keys","API-lykill"]},{"id":"accesstoken","g":"sec","word":"Aðgangsmerki","text":"Tímabundinn passi er sannar at forrit hafi leyfi til inngöngu, svá at lykilorð þitt þurfi eigi í hvert sinn. Eigi hit sama ok AI-token.","also":["Access token","access tokens","aðgangsmerki"]},{"id":"encryption","g":"sec","word":"Dulkóðun","text":"At rugla upplýsingum svá at aðeins sá er hefir réttan lykil megi lesa þær.","also":["Encryption","encrypted","encrypt","dulkóðun"]},{"id":"https","g":"sec","word":"HTTPS","text":"Hinn öruggi háttr er vefsíður ferðask, sýndr með lásnum í vafranum, svá at enginn á milli megi lesa þær eða breyta."},{"id":"cert","g":"sec","word":"SSL/TLS-vottorð","text":"Rafrænt skilríki er lætr vefsíðu sanna hver hon er ok nota HTTPS. Þat rennr út, svá at endrnýja verðr þat.","also":["TLS certificate","SSL certificate","certificate","certificates","vottorð"]},{"id":"permissions","g":"sec","word":"Heimildir","text":"Reglur um hverr má sjá eða breyta hverju.","also":["Permissions","permission","heimildir"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Minnstu réttindi","text":"At gefa hverjum manni eða forriti aðeins þann aðgang er hann sannarlega þarf, ok aðeins svá lengi sem hann þarf hans.","also":["Least privilege","principle of least privilege","minnstu réttindi"]},{"id":"rbac","g":"sec","word":"Aðgangsstýring eftir hlutverki (RBAC)","text":"At veita aðgang eftir hlutverki, svá sem áhorfandi eða ritstjóri, en eigi mann fyrir mann.","also":["RBAC","role-based access","role-based access control","aðgangsstýring eftir hlutverki"]},{"id":"vuln","g":"sec","word":"Veikleiki","text":"Veikleiki er einhver gæti notat til at brjótast inn eða valda tjóni.","also":["Vulnerability","vulnerabilities","veikleiki"]},{"id":"zeroday","g":"sec","word":"Núlldagr","text":"Veikleiki sem árásarmenn þekkja áðr en smiðirnir hafa haft nokkurn tíma til at laga hann.","also":["Zero-day","zero-days","zero day","núlldagr"]},{"id":"malware","g":"sec","word":"Illgengishugbúnaðr","text":"Skaðlegr hugbúnaðr, svá sem vírusar, gerðr til at skemma, njósna eða stela.","also":["Malware","illgengishugbúnaðr"]},{"id":"ransomware","g":"sec","word":"Lausnargjaldshugbúnaðr","text":"Illgengishugbúnaðr er læsir skrám þínum ok krefst fjár til at opna þær. Góð afrit eru bezta vörn.","also":["Ransomware","ransomware attack","lausnargjaldshugbúnaðr"]},{"id":"phishing","g":"sec","word":"Veiðipóstr","text":"Fölsk boð er reyna at tæla þik til at gefa upp lykilorð eða fé, eða opna eitthvat skaðlegt.","also":["Phishing","phishing email","phishing emails","veiðipóstr"]},{"id":"socialeng","g":"sec","word":"Félagsleg blekking","text":"At blekkja menn, en eigi tölvur, til at veita aðgang, svá sem með fölsku kalli frá „upplýsingatæknistuðningi“."},{"id":"firewall","g":"sec","word":"Eldveggr","text":"Vörðr er ræðr hver netumferð má koma inn eða fara út.","also":["Firewall","firewalls","eldveggr"]},{"id":"vpn","g":"sec","word":"VPN","text":"Stytting á virtual private network: einkatenging ok dulin um netit, oft notuð til at komast örugglega í vinnukerfi.","also":["VPN","virtual private network","sýndareinkanet"]},{"id":"ddos","g":"sec","word":"Þjónustuhindrun (DoS, DDoS)","text":"At flæða yfir þjónustu með svá mikilli falskri umferð at raunverulegir menn megi eigi nota hana. DDoS merkir at hon komi frá mörgum tölvum í senn.","also":["DoS","DDoS","denial of service","DDoS attack","þjónustuhindrun"]},{"id":"pentest","g":"sec","word":"Innbrotspróf (pen test)","text":"At ráða vinveitta sérfræðinga til at reyna innbrot, svá at veikleikar finnisk áðr en raunverulegir árásarmenn finna þá.","also":["pen test","pen testing","penetration testing","pentest","innbrotspróf"]},{"id":"audit","g":"sec","word":"Öryggisúttekt","text":"Nákvæm könnun á því hversu vel eitthvat er varit, borin saman við lista góðra starfshátta.","also":["Security audit","security audits","öryggisúttekt"]},{"id":"threatmodel","g":"sec","word":"Ógnarmótun","text":"At hugsa fyrirfram hverr gæti ráðizt á eitthvat, hvernig, ok hvat þú myndir gera til at stöðva þá.","also":["Threat modelling","threat model","threat modeling","ógnarmótun"]},{"id":"breach","g":"sec","word":"Gagnaleki","text":"Er einkaupplýsingar komask til þeirra er eigi skyldu hafa þær, eða týnask eða breytask án leyfis.","also":["Data breach","data breaches","gagnaleki"]},{"id":"pii","g":"sec","word":"Persónuupplýsingar","text":"Allar upplýsingar um mann er auðkenna má, svá sem nafn, tölvupóstfang eða staðsetning. Kallat einnig PII.","also":["Personal data","PII","personally identifiable information","persónuupplýsingar"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Evrópsk lög um persónuupplýsingar (Bretland hefir sína eigin gerð): safna aðeins því er þarf, geyma þat örugglega, ok láta menn sjá eða eyða sínum eigin.","also":["GDPR","General Data Protection Regulation","persónuverndarreglugerð"]},{"id":"dataprot","g":"sec","word":"Gagnavernd","text":"At annast persónuupplýsingar rétt ok innan laga.","also":["Data protection","data protection law","gagnavernd"]},{"id":"privacypolicy","g":"sec","word":"Persónuverndarstefna","text":"Opinber síða er segir hvaða persónuupplýsingum þú safnar, hví, ok hvat þú gerir við þær.","also":["Privacy policy","privacy statement","privacy notice","persónuverndarstefna"]},{"id":"consent","g":"sec","word":"Samþykki","text":"Skýrt ok frjálst já manns við því at gögn hans séu notuð á tiltekinn hátt. Hann má taka þat aftr hvenær sem er.","also":["Consent","opt-in","samþykki"],"noTip":1},{"id":"cookie","g":"sec","word":"Kaka","text":"Lítil skrá er vefsíða geymir í vafra þínum til at muna hluti, svá sem at þú sért innskráðr. Sumar krefjast fyrst samþykkis þíns.","also":["Cookie","cookies","kaka"],"noTip":1},{"id":"minimisation","g":"sec","word":"Gagnasparnaðr","text":"At safna ok geyma aðeins þær persónuupplýsingar er verkit krefst í raun.","also":["Data minimisation","data minimization","gagnasparnaðr"]},{"id":"retention","g":"sec","word":"Gagnageymslutími","text":"Hversu lengi gögn eru geymd áðr en þeim er eytt. At geyma þau eigi lengr en þarf er öruggara ok oft skylt at lögum.","also":["Data retention","retention period","gagnageymslutími"]},{"id":"anon","g":"sec","word":"Nafnleynd","text":"At breyta gögnum svá at engan megi framar með rökum auðkenna af þeim.","also":["Anonymisation","anonymised","anonymization","anonymous data","nafnleynd"]},{"id":"pseudo","g":"sec","word":"Dulnefning","text":"At skipta nöfnum ok öðrum smáatriðum út fyrir kóða, með lykil geymdan sér til at tengja þau aftr. Þetta eru enn persónuupplýsingar.","also":["Pseudonymisation","pseudonymised","pseudonymization","dulnefning"]},{"id":"dpa","g":"sec","word":"Vinnslusamningr gagna (DPA)","text":"Samningr er segir hvernig birgir má fara með persónuupplýsingar fyrir þína hönd.","also":["DPA","data processing agreement","vinnslusamningr gagna"]},{"id":"dpia","g":"sec","word":"Mat á áhrifum gagnaverndar (DPIA)","text":"Nákvæm skoðun, áðr en þú hefr, á því hvernig áætlun um notkun persónuupplýsinga gæti snert menn ok hvernig draga megi úr áhættu.","also":["DPIA","data protection impact assessment","mat á áhrifum gagnaverndar"]},{"id":"auditlog","g":"sec","word":"Úttektarannáll","text":"Skrá um hverr gerði hvat ok hvenær, svá at kanna megi aðgerðir síðar.","also":["Audit log","audit logs","audit trail","úttektarannáll"]},{"id":"compliance","g":"sec","word":"Reglufylgni","text":"At fylgja þeim lögum, reglum ok stöðlum er gilda um þik, ok geta sýnt at þú gerir þat.","also":["Compliance","compliant","reglufylgni"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Þekktr alþjóðlegr staðall um stjórn upplýsingaöryggis. Fyrirtæki geta fengit vottun eftir honum.","also":["ISO/IEC 27001","ISO 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Bandarísk skýrsla, könnuð af utanaðkomandi endrskoðendum, er sýnir at fyrirtæki gætir gagna kaupenda vel.","also":["SOC2","SOC 2"]},{"id":"agent","g":"ai","word":"Agent","text":"Gervigreind sú er vinnr verk sjálf: les kóðann, gerir breytingar, keyrir prófanir ok skýrir frá. Verk hennar er þó enn kannat.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"Smáir textabútar er gervigreind les ok ritar, hverr um þrír fjórðu hlutar orðs. Gervigreindarnotkun er talin í tokenum, svá at færri token skilja meira eftir af áætlun þinni.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Lítil skipun er keyrir sjálfkrafa á ákveðinni stundu, til dæmis er gervigreindarseta hefst, svá at sveitin heyri athugasemdir þínar.","also":["hooks"]},{"id":"ai","g":"ai","word":"Gervigreind (AI)","text":"Tölvukerfi er gera þat sem vér ætlum yfirleitt þurfa mann, svá sem at rita, svara spurningum eða þekkja myndir.","also":["AI","artificial intelligence","gervigreind"],"noTip":1},{"id":"ml","g":"ai","word":"Vélnám (ML)","text":"Háttr til at láta tölvur læra mynstr af mörgum dæmum, í stað þess at gefa þeim nákvæmar reglur.","also":["machine learning","ML","vélnám"]},{"id":"model","g":"ai","word":"Líkan","text":"Þjálfaðr „heili“ gervigreindarkerfis, smíðaðr með því at læra af ógrynni dæma. Líkön eru ólík í kunnáttu, hraða ok verði.","also":["Model","models","AI model","líkan"],"noTip":1},{"id":"llm","g":"ai","word":"Stórt tungumálslíkan (LLM)","text":"Gervigreindarlíkan þjálfat á ógrynni texta, svá at þat getr lesit ok ritat mál.","also":["LLM","LLMs","large language model","stórt tungumálslíkan"]},{"id":"genai","g":"ai","word":"Skapandi gervigreind","text":"Gervigreind er býr til nýja hluti, svá sem texta, myndir eða kóða, en flokkar eða þekkir eigi aðeins.","also":["Generative AI","GenAI","skapandi gervigreind"]},{"id":"chatbot","g":"ai","word":"Spjallmenni","text":"Forrit er þú talar við á daglegu máli, með ritun eða tali.","also":["Chatbot","chatbots","spjallmenni"]},{"id":"prompt","g":"ai","word":"Fyrirmæli","text":"Þat er þú gefr gervigreind: spurning þín eða fyrirskipanir, auk alls sem þú réttir henni. Skýrari fyrirmæli gefa oftast betri svör.","also":["Prompt","prompts","fyrirmæli"]},{"id":"prompteng","g":"ai","word":"Fyrirmælasmíð","text":"Kunnátta at rita fyrirmæli er gefa áreiðanlegan ok gagnligan árangr.","also":["Prompt engineering","fyrirmælasmíð"]},{"id":"sysprompt","g":"ai","word":"Kerfisfyrirmæli","text":"Bakgrunnsfyrirmæli er gervigreind fær áðr en samtal hefst, er setja hlutverk hennar ok reglur. Þau vega meira en þat er þú ritar.","also":["System prompt","system prompts","system instruction","system instructions","kerfisfyrirmæli"]},{"id":"context","g":"ai","word":"Samhengi","text":"Allt sem gervigreind sér meðan hon vinnr: fyrirmælin, boð þín, skrár er hon hefir lesit ok fyrri svör.","noTip":1},{"id":"ctxwin","g":"ai","word":"Samhengisgluggi","text":"Hversu mikit gervigreind getr haldit í huga í senn, mælt í tokenum. Handan þess eru eldri hlutar felldir burt eða dregnir saman.","also":["Context window","context windows","samhengisgluggi"]},{"id":"session","g":"ai","word":"Seta","text":"Eitt vinnusamtal við gervigreind, frá upphafi til enda. Ný seta hefst með nýju minni.","also":["Session","sessions","seta"],"noTip":1},{"id":"memory","g":"ai","word":"Minni","text":"Minnisblöð er gervigreind geymir milli setna, svá at hon muni óskir þínar ok fyrri ákvarðanir.","noTip":1},{"id":"hallucination","g":"ai","word":"Ofskynjun","text":"Er gervigreind segir eitthvat með fullri vissu sem er tilbúit eða rangt. Kanna skaltu mikilvæg atriði.","also":["Hallucination","hallucinations","hallucinate","hallucinates","ofskynjun"]},{"id":"training","g":"ai","word":"Þjálfun","text":"At kenna líkani með því at sýna því ógrynni dæma, áðr en nokkur notar þat.","also":["Training","trained","þjálfun"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Þjálfunargögn","text":"Dæmin er líkan lærði af. Þekking þess stöðvask á þeim degi er gögnunum var safnat.","also":["Training data","training set","þjálfunargögn"]},{"id":"cutoff","g":"ai","word":"Þekkingarmörk","text":"Sá dagr er innri þekking gervigreindar endar. Hún veit eigi um síðari hluti nema hún leiti þeirra.","also":["Knowledge cutoff","training cutoff","þekkingarmörk"]},{"id":"finetune","g":"ai","word":"Fínstilling","text":"Aukin þjálfun fyrirliggjandi líkans á þínum eigin dæmum, til at gera þat betra í einu tilteknu verki.","also":["Fine-tuning","fine-tune","fine-tuned","fine tuning","fínstilling"]},{"id":"inference","g":"ai","word":"Ályktun líkans","text":"Þá er gervigreindarlíkan er í raun notat til at svara einhverju, öndvert við þjálfun.","also":["Inference","model inference","ályktun líkans"]},{"id":"tooluse","g":"ai","word":"Verkfæranotkun","text":"At gervigreind megi gera hluti, en eigi aðeins tala: keyra skipanir, lesa skrár eða leita á vefnum, með verkfærum er forritit gefr henni.","also":["Tool use","tool calling","tool call","tool calls","verkfæranotkun"]},{"id":"subagent","g":"ai","word":"Undirerindreki","text":"Hjálpar-gervigreind er aðalgervigreind felr smærra verk, ok fær árangrinn aftr frá henni.","also":["Subagent","subagents","sub-agent","undirerindreki"]},{"id":"multiagent","g":"ai","word":"Margir erindrekar","text":"Margar gervigreindir er vinna saman at einu verki, hver með sinn hluta, sem lítil sveit.","also":["Multi-agent","multi-agent system","margir erindrekar"]},{"id":"autonomy","g":"ai","word":"Sjálfræði","text":"Hversu mikit gervigreind má gera sjálf áðr en hon verðr at spyrja mann.","also":["Autonomy","autonomous","sjálfræði"]},{"id":"hitl","g":"ai","word":"Maðr í hringnum","text":"At hafa mann með í ráðum til at kanna eða samþykkja þat er gervigreind gerir á lykilstöðum. Í AI-gile er þat þú.","also":["Human in the loop","human-in-the-loop","HITL","maðr í hringnum"]},{"id":"guardrails","g":"ai","word":"Handrið","text":"Takmörk ok prófanir er halda aðgerðum gervigreindar öruggum, svá sem at krefjast samþykkis áðr en nokkut fer í loft. Þau draga úr hættu á mistökum, en útiloka þau eigi.","also":["Guardrails","guardrail","handrið"]},{"id":"rag","g":"ai","word":"Leitaraukin sköpun (RAG)","text":"At láta gervigreind fletta upp í skjölum þínum áðr en hon svarar, svá at svör hennar byggi á þínum staðreyndum.","also":["RAG","retrieval augmented generation","Retrieval-augmented generation","leitaraukin sköpun"]},{"id":"embedding","g":"ai","word":"Merkingarvigr","text":"At breyta texta í lista talna er geymir merkingu hans, svá at tölva megi finna hluti er merkja svipað.","also":["Embedding","embeddings","merkingarvigr"]},{"id":"vectordb","g":"ai","word":"Vigragrunnr","text":"Gagnagrunnr smíðaðr til at leita í þeim talnalistum (embeddings), til at finna efni með svipaða merkingu.","also":["Vector database","vector databases","vector store","vigragrunnr"]},{"id":"mcp","g":"ai","word":"Samhengissamskiptaregla líkans (MCP)","text":"Sameiginlegr háttr til at tengja verkfæri ok gagnalindir við gervigreindarforrit, svá at gervigreind megi nota þau.","also":["MCP","Model Context Protocol","samskiptaregla"]},{"id":"temperature","g":"ai","word":"Hiti (temperature)","text":"Stilling um hversu djörf svör gervigreindar eru. Lágt gefr stöðugri ok fyrirsjáanlegri svör; hátt gefr fjölbreyttari. Hvárugt gerir hana æ rétta.","also":["Temperature","model temperature","hiti"],"noTip":1},{"id":"multimodal","g":"ai","word":"Fjölháttað","text":"Fær um at vinna með fleiri en eina tegund upplýsinga, svá sem texta, myndir ok hljóð.","also":["Multimodal","multi-modal","fjölháttað"]},{"id":"evals","g":"ai","word":"Mat (eval)","text":"Áætluð prófun á því hversu vel gervigreind gerir á völdum dæmum, svá at bera megi saman líkön eða fyrirmæli.","also":["Evaluation","eval","evals","mat"]},{"id":"bias","g":"ai","word":"Hlutdrægni","text":"Er gervigreind (eða maðr) hallask ranglega til einnar hliðar, oft vegna þess er hún lærði af.","also":["Bias","biased","hlutdrægni"],"noTip":1},{"id":"responsible","g":"ai","word":"Ábyrg gervigreind","text":"At nota gervigreind réttlátlega, örugglega ok heiðarlega, svá at menn svari enn fyrir árangrinum.","also":["Responsible AI","ethical AI","ábyrg gervigreind"]},{"id":"injection","g":"ai","word":"Fyrirmælaíblöndun","text":"Bragð þar sem falin fyrirmæli í vefsíðu eða skrá reyna at láta gervigreind gera þat er notandi hennar bað eigi um.","also":["Prompt injection","prompt injections","fyrirmælaíblöndun"]},{"id":"ratelimit","g":"ai","word":"Beiðnamörk","text":"Hámark þess hversu margar beiðnir þú mátt senda þjónustu á tilteknum tíma. Ef þú ferr yfir verðr þú at bíða.","also":["Rate limit","rate limits","rate limited","beiðnamörk"]},{"id":"usagelimit","g":"ai","word":"Notkunarmörk","text":"Hversu mikla gervigreindarvinnu áætlun þín leyfir á tímabili, eftir þat er hon gerir hlé eða kostar meira.","also":["Usage limit","usage limits","notkunarmörk"]},{"id":"vibe","g":"ai","word":"Vibe-forritun","text":"At smíða hugbúnað mestmegnis með því at lýsa fyrir gervigreind hvat þú vilt ok láta hana rita kóðann.","also":["Vibe coding","vibe-coding","vibe-forritun"]},{"id":"budget","g":"money","word":"Fjárhagsáætlun","text":"Fjárhæð sú er ætluð er til einhvers hlutar.","also":["Budget","budgets","fjárhagsáætlun"],"noTip":1},{"id":"costest","g":"money","word":"Kostnaðarmat","text":"Bezta gizkan um hvat eitthvat mun kosta áðr en þú hefr.","also":["Cost estimate","cost estimates","kostnaðarmat"]},{"id":"roi","g":"money","word":"Ávöxtun fjárfestingar (ROI)","text":"Hvat þú færð aftr í samanburði við þat er þú lagðir í. Ef þat er jákvætt var þat vert.","also":["ROI","return on investment","ávöxtun"]},{"id":"tco","g":"money","word":"Heildarkostnaðr eignar (TCO)","text":"Allt sem eitthvat í raun kostar yfir alla ævi þess, eigi aðeins kaupverð: rekstr, stuðningr, uppfærslur ok loks at leggja þat niðr.","also":["TCO","total cost of ownership","heildarkostnaðr eignar"]},{"id":"capex","g":"money","word":"CapEx ok OpEx","text":"CapEx er fé varit fyrirfram í hluti er þú heldr; OpEx er áframhaldandi útgjöld, svá sem mánaðarreikningar.","also":["CapEx","OpEx","capital expenditure","operating expenditure","stofnkostnaðr","rekstrarkostnaðr"]},{"id":"subscription","g":"money","word":"Áskrift","text":"At greiða reglulega, oftast mánaðarlega eða árlega, til at halda áfram at nota eitthvat.","also":["Subscription","subscriptions","áskrift"],"noTip":1},{"id":"saas","g":"money","word":"Hugbúnaðr sem þjónusta (SaaS)","text":"Hugbúnaðr er þú notar á netinu ok greiðir fyrir með áskrift, meðan smiðrinn rekr hann fyrir þik.","also":["SaaS","Software as a service","hugbúnaðr sem þjónusta"]},{"id":"payg","g":"money","word":"Greiða eftir notkun","text":"At greiða aðeins fyrir þat er þú notar, svá sem skýjatölvun eða gervigreindar-token.","also":["Pay as you go","pay-as-you-go","usage-based pricing","greiða eftir notkun"]},{"id":"overage","g":"money","word":"Umframnotkun","text":"Notkun umfram þat er áætlun þín nær yfir, sem getr kostat aukalega.","also":["Overage","overages","overage charges","umframnotkun"]},{"id":"billingalert","g":"money","word":"Reikningsviðvörun","text":"Boð er kemr þá er útgjöld eða notkun ná stigi er þú valdir. Þat varar þik við, en stöðvar eigi alltaf frekari gjöld.","also":["Billing alert","billing alerts","spending alert","reikningsviðvörun"]},{"id":"freetier","g":"money","word":"Ókeypis stig","text":"Ókeypis stig greiddrar þjónustu, með takmörkum. Hentugt til at byrja.","also":["Free tier","free plan","ókeypis stig"]},{"id":"pricing","g":"money","word":"Verðáætlun","text":"Hinir ýmsu pakkar er þjónusta selr, hverr með sitt verð ok takmörk.","also":["Pricing plan","pricing plans","price plan","verðáætlun"]},{"id":"licence","g":"money","word":"Leyfi","text":"Reglur um hvernig þú mátt nota, afrita, breyta eða deila því er annarr gerði, svá sem hugbúnaði, letri eða myndum.","also":["Licence","licences","license","licenses","leyfi"],"noTip":1},{"id":"opensource","g":"money","word":"Opinn hugbúnaðr","text":"Hugbúnaðr sem hverr sem er má lesa, nota ok oft breyta ókeypis, eftir reglum leyfis hans.","also":["Open source","open-source","open source software","OSS","opinn hugbúnaðr"]},{"id":"osslicence","g":"money","word":"Leyfi opins hugbúnaðar","text":"Reglurnar er fylgja opnum kóða. Sum leyfa nær allt (svá sem MIT); sum biðja þik deila breytingum þínum einnig (svá sem GPL).","also":["Open source licence","open source licences","MIT licence","GPL","leyfi opins hugbúnaðar"]},{"id":"proprietary","g":"money","word":"Einkaeign","text":"Í eigu fyrirtækis ok eigi frjálst at afrita eða breyta. Andstæða opins hugbúnaðar.","also":["Proprietary","proprietary software","einkaeign"]},{"id":"copyright","g":"money","word":"Höfundarréttr","text":"Lagalegr réttr höfundar til at ráða afritum verks síns, einnig kóða ok ritverka.","also":["Copyright","copyrighted","höfundarréttr"],"noTip":1},{"id":"ip","g":"money","word":"Hugverk (IP)","text":"Hugmyndir ok verk er lög telja í eigu einhvers, svá sem kóði, hönnun, nöfn ok merki.","also":["IP","intellectual property","hugverk"]},{"id":"tos","g":"money","word":"Þjónustuskilmálar","text":"Reglur er þú samþykkir er þú notar þjónustu.","also":["Terms of service","terms and conditions","terms of use","þjónustuskilmálar"]},{"id":"contract","g":"money","word":"Samningr","text":"Rituð samkoma tveggja aðila er lög styðja.","also":["Contract","contracts","samningr"],"noTip":1},{"id":"sow","g":"money","word":"Verklýsing (SOW)","text":"Skjal er segir nákvæmlega hvert verk skal unnit, fyrir hvenær ok fyrir hversu mikit.","also":["SOW","Statement of work","verklýsing"]},{"id":"fixedprice","g":"money","word":"Fast verð","text":"Samit verð fyrir allt verkit, hversu lengi sem þat tekr.","also":["Fixed price","fixed-price","fast verð"]},{"id":"tm","g":"money","word":"Tími ok efni","text":"At greiða fyrir stundir er raunverulega voru unnar ok hluti er raunverulega voru notaðir, en eigi fast verð.","also":["Time and materials","T&M","tími ok efni"]},{"id":"invoice","g":"money","word":"Reikningr","text":"Reikningr er krefr greiðslu fyrir unnit verk eða afhentar vörur.","also":["Invoice","invoices","reikningr"],"noTip":1},{"id":"lockin","g":"money","word":"Binding við birgi","text":"Er svá erfitt eða dýrt at yfirgefa birgi at þú ert fastr hjá honum.","also":["Vendor lock-in","lock-in","binding við birgi"]},{"id":"procurement","g":"money","word":"Innkaup","text":"Ferli at velja ok kaupa af birgjum.","also":["Procurement","innkaup"]},{"id":"servicecredit","g":"money","word":"Þjónustuinneign","text":"Endrgreiðsla eða afsláttr er þú færð þá er birgir bregzt SLA sínu.","also":["Service credit","service credits","þjónustuinneign"]}]}};
